// Fase 4: toda la interfaz es React. El island imperativo queda reducido a
// GolfGame + red tras GameHost; hud.ts solo escribe los nodos de 60 Hz
// (marcadores, viento, medidor de tiro, toast, panel de resultado).
import { useEffect } from 'react';
import { GameCanvas } from './ui/GameCanvas';
import { IconSprite } from './ui/IconSprite';
import { BootError } from './ui/BootError';
import { HudLayer } from './ui/HudLayer';
import { MenuRoot } from './ui/menu/MenuRoot';
import { MessagePanel } from './ui/panels/MessagePanel';
import { MatchOverPanel } from './ui/panels/MatchOverPanel';
import { GameMenuPanel } from './ui/panels/GameMenuPanel';
import { MapVotePanel } from './ui/panels/MapVotePanel';
import { ReconnectPanel } from './ui/panels/ReconnectPanel';
import { JoinPasswordPanel } from './ui/panels/JoinPasswordPanel';
import { useGlobalKeys } from './ui/hooks/useGlobalKeys';
import { bootApp, destroyApp } from './bridge/legacyBoot';

export function App() {
  useGlobalKeys();

  useEffect(() => {
    bootApp();
    return () => destroyApp();
  }, []);

  return (
    <>
      <IconSprite />
      <main className="app-shell">
        <GameCanvas />
        <div className="scanline-overlay" aria-hidden="true" />
        <HudLayer />
        <MessagePanel />
        <MatchOverPanel />
        <GameMenuPanel />
        <ReconnectPanel />
        <MapVotePanel />
        <MenuRoot />
        <JoinPasswordPanel />
        <BootError />
      </main>
    </>
  );
}
