import { useEffect, useRef } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';
import { CreateConfigState, CREATE_DEFAULTS, WORLD_IDS, WorldId } from '../../bridge/createConfig';

interface RuleCardProps {
  rule: string;
  title: string;
  hintId: string;
  hint: string;
  toggleLabel: string;
  enabled: boolean;
  onToggle: (enabled: boolean) => void;
  inputId: string;
  value: string;
  onValue: (value: string) => void;
  min: number; max: number; step: number;
  unit: string;
  offText: string;
}

function RuleCard(props: RuleCardProps) {
  return (
    <article className="rule-card" data-rule={props.rule} data-enabled={String(props.enabled)}>
      <div className="rule-card-head">
        <div><strong>{props.title}</strong><small id={props.hintId}>{props.hint}</small></div>
        <label className="toggle-field compact" aria-label={props.toggleLabel}>
          <input type="checkbox" role="switch" aria-describedby={props.hintId} checked={props.enabled} onChange={(e) => props.onToggle(e.target.checked)} />
          <i />
        </label>
      </div>
      <label className="rule-value" htmlFor={props.inputId}>
        <input
          id={props.inputId} type="number" min={props.min} max={props.max} step={props.step}
          disabled={!props.enabled} value={props.value} onChange={(e) => props.onValue(e.target.value)}
        />
        <span>{props.unit}</span>
      </label>
      <b className="rule-state" data-off={String(!props.enabled)}>{props.enabled ? 'ACTIVO' : props.offText}</b>
    </article>
  );
}

const WORLD_META: Array<{ id: WorldId; title: string; sub: string }> = [
  { id: 'meadow', title: 'Pradera alta', sub: 'Terreno abierto y equilibrado' },
  { id: 'sky-islands', title: 'Islas flotantes', sub: 'Saltos, vacío y viento' },
  { id: 'cavern', title: 'Cañón y túneles', sub: 'Techos y rutas cerradas' },
  { id: 'aqua-cavern', title: 'Cuevas submarinas', sub: 'Gravedad y ambiente abisal' },
  { id: 'hybrid', title: 'Ruta híbrida', sub: 'Superficie, islas y cuevas' },
  { id: 'glacier', title: 'Glaciar cinético', sub: 'Hielo y obstáculos móviles' },
];

interface Props {
  cfg: CreateConfigState;
  patch: (p: Partial<CreateConfigState>) => void;
  liveStatus: string;
  setLiveStatus: (text: string) => void;
}

export function MatchConfigPanel({ cfg, patch, liveStatus, setLiveStatus }: Props) {
  const snap = useSession();
  const open = snap.modals.includes('matchConfig');
  const closeRef = useRef<HTMLButtonElement>(null);
  const battle = cfg.mode === 'battle';

  useEffect(() => {
    if (open) {
      const t = window.setTimeout(() => closeRef.current?.focus(), 20);
      return () => window.clearTimeout(t);
    }
  }, [open]);

  const toggleWorld = (id: WorldId, checked: boolean) => {
    const next = checked ? [...new Set([...cfg.allowedWorlds, id])] : cfg.allowedWorlds.filter((w) => w !== id);
    if (!next.length) {
      setLiveStatus('Debe quedar al menos un mundo ambiental activo.');
      return;
    }
    patch({ allowedWorlds: next });
  };

  const reset = () => {
    patch({
      maxPlayers: String(CREATE_DEFAULTS.maxPlayers),
      pointsEnabled: CREATE_DEFAULTS.pointsEnabled,
      maxPoints: String(CREATE_DEFAULTS.maxPoints),
      worldTimeEnabled: CREATE_DEFAULTS.worldTimeEnabled,
      worldTimeSeconds: String(CREATE_DEFAULTS.worldTimeSeconds),
      finishTimeEnabled: CREATE_DEFAULTS.finishTimeEnabled,
      finishTimeSeconds: String(CREATE_DEFAULTS.finishTimeSeconds),
      turnLimitEnabled: CREATE_DEFAULTS.turnLimitEnabled,
      turnLimit: String(CREATE_DEFAULTS.turnLimit),
      collisionsEnabled: CREATE_DEFAULTS.collisionsEnabled,
      allowedWorlds: [...WORLD_IDS],
    });
    setLiveStatus('Se restauraron las reglas recomendadas.');
  };

  return (
    <section
      id="matchConfigPanel"
      className={`mini-modal match-config-modal${open ? '' : ' hidden'}`}
      role="dialog" aria-modal="true" aria-labelledby="matchConfigTitle"
      onClick={(event) => { if (event.target === event.currentTarget) sessionStore.closeModal('matchConfig'); }}
    >
      <div className="mini-modal-card config-modal-card">
        <header className="config-modal-head">
          <div>
            <span className="kicker">REGLAS DE LA SALA</span>
            <h2 id="matchConfigTitle">Configurar partida</h2>
            <p>Define cómo se gana, cuándo cambia el mundo y qué ambientes pueden aparecer.</p>
          </div>
          <button
            id="closeMatchConfigBtn" ref={closeRef} className="icon-button" type="button"
            aria-label="Cerrar configuración" onClick={() => sessionStore.closeModal('matchConfig')}
          >
            <svg className="ico" aria-hidden="true"><use href="#i-close" /></svg>
          </button>
        </header>

        <div className="config-modal-scroll">
          <section className="config-section" aria-labelledby="gameModeTitle">
            <div className="config-section-head">
              <span className="config-section-icon"><svg className="ico" aria-hidden="true"><use href="#i-swords" /></svg></span>
              <div><h3 id="gameModeTitle">Modo de juego</h3><p>Elige cómo participan los jugadores durante cada mundo.</p></div>
            </div>
            <div className="mode-selector" role="group" aria-label="Modo de juego">
              <button
                className={`mode-option${!battle ? ' active' : ''}`} type="button" data-mode="turn"
                aria-pressed={!battle} onClick={() => patch({ mode: 'turn' })}
              >
                <span className="mode-option-icon"><svg className="ico" aria-hidden="true"><use href="#i-turns" /></svg></span>
                <strong>POR TURNOS</strong>
                <small>Un jugador lanza cada vez. La cámara sigue al jugador activo y el turno avanza cuando su bola se detiene.</small>
              </button>
              <button
                className={`mode-option${battle ? ' active' : ''}`} type="button" data-mode="battle"
                aria-pressed={battle} onClick={() => patch({ mode: 'battle' })}
              >
                <span className="mode-option-icon"><svg className="ico" aria-hidden="true"><use href="#i-swords" /></svg></span>
                <strong>BATTLE ROYALE</strong>
                <small>Todos lanzan al mismo tiempo. Las bolas pueden colisionar y llegar antes al hoyo concede bonus de posición.</small>
              </button>
            </div>
          </section>

          <section className="config-section" aria-labelledby="roomCapacityTitle">
            <div className="config-section-head">
              <span className="config-section-icon"><svg className="ico" aria-hidden="true"><use href="#i-users" /></svg></span>
              <div><h3 id="roomCapacityTitle">Capacidad</h3><p>El host ocupa uno de los espacios disponibles.</p></div>
            </div>
            <label className="config-number-row" htmlFor="createMaxPlayers">
              <span><strong>Máximo de jugadores</strong><small>Entre 2 y 16 jugadores.</small></span>
              <span className="number-control">
                <input id="createMaxPlayers" type="number" min={2} max={16} step={1} value={cfg.maxPlayers} onChange={(e) => patch({ maxPlayers: e.target.value })} />
                <b>jug.</b>
              </span>
            </label>
          </section>

          <section className="config-section" aria-labelledby="matchRulesTitle">
            <div className="config-section-head">
              <span className="config-section-icon"><svg className="ico" aria-hidden="true"><use href="#i-trophy" /></svg></span>
              <div><h3 id="matchRulesTitle">Victoria y ritmo</h3><p>Al apagar una regla, su campo se desactiva; puntos, tiempo global y turnos quedan sin límite.</p></div>
            </div>
            <div className="rule-grid">
              <RuleCard
                rule="points" title="Puntos máximos para ganar" hintId="pointsRuleHint"
                hint="La partida termina al alcanzar esta meta." toggleLabel="Activar puntos máximos"
                enabled={cfg.pointsEnabled} onToggle={(v) => { patch({ pointsEnabled: v }); setLiveStatus('Configuración actualizada.'); }}
                inputId="createMaxPoints" value={cfg.maxPoints} onValue={(v) => patch({ maxPoints: v })}
                min={500} max={1000000} step={500} unit="puntos" offText="INFINITO"
              />
              <RuleCard
                rule="world-time" title="Tiempo por mundo" hintId="worldTimeRuleHint"
                hint="Límite para completar cada mundo." toggleLabel="Activar tiempo por mundo"
                enabled={cfg.worldTimeEnabled} onToggle={(v) => { patch({ worldTimeEnabled: v }); setLiveStatus('Configuración actualizada.'); }}
                inputId="createWorldTimeSeconds" value={cfg.worldTimeSeconds} onValue={(v) => patch({ worldTimeSeconds: v })}
                min={30} max={1800} step={30} unit="segundos" offText="INFINITO"
              />
              <RuleCard
                rule="finish-time" title="Tiempo restante al embocar" hintId="finishTimeRuleHint"
                hint="Cuando alguien llega, este contador reemplaza el tiempo del mundo para los demás." toggleLabel="Activar tiempo restante al embocar"
                enabled={cfg.finishTimeEnabled} onToggle={(v) => { patch({ finishTimeEnabled: v }); setLiveStatus('Configuración actualizada.'); }}
                inputId="createFinishTimeSeconds" value={cfg.finishTimeSeconds} onValue={(v) => patch({ finishTimeSeconds: v })}
                min={10} max={300} step={5} unit="segundos" offText="DESACTIVADO"
              />
              <RuleCard
                rule="turn-limit" title="Turnos por mundo" hintId="turnLimitRuleHint"
                hint="Cada lanzamiento consume un turno; quien agote el límite no puntúa." toggleLabel="Activar límite de turnos"
                enabled={cfg.turnLimitEnabled} onToggle={(v) => { patch({ turnLimitEnabled: v }); setLiveStatus('Configuración actualizada.'); }}
                inputId="createTurnLimit" value={cfg.turnLimit} onValue={(v) => patch({ turnLimit: v })}
                min={1} max={100} step={1} unit="turnos" offText="INFINITO"
              />
            </div>
          </section>

          <fieldset className="config-section world-picker" aria-describedby="worldPickerHint">
            <legend className="config-section-head">
              <span className="config-section-icon"><svg className="ico" aria-hidden="true"><use href="#i-globe" /></svg></span>
              <span><strong>Mundos ambientales</strong><small id="worldPickerHint">Debe quedar al menos uno activo. Un ambiente desactivado nunca se generará.</small></span>
            </legend>
            <div className="world-options">
              {WORLD_META.map((world) => (
                <label key={world.id} className="world-option" data-world={world.id}>
                  <input
                    type="checkbox" name="allowedWorld" value={world.id}
                    checked={cfg.allowedWorlds.includes(world.id)}
                    onChange={(e) => toggleWorld(world.id, e.target.checked)}
                  />
                  <i />
                  <span><strong>{world.title}</strong><small>{world.sub}</small></span>
                </label>
              ))}
            </div>
          </fieldset>

          <section className="config-section" aria-labelledby="extraRulesTitle">
            <div className="config-section-head">
              <span className="config-section-icon"><svg className="ico" aria-hidden="true"><use href="#i-settings" /></svg></span>
              <div><h3 id="extraRulesTitle">Reglas adicionales</h3><p>Opciones de jugabilidad visibles para todos antes de entrar.</p></div>
            </div>
            <div className="extra-rule-grid">
              <label className="extra-rule" id="collisionRule" data-unavailable={String(!battle)}>
                <span><strong>Colisiones entre bolas</strong><small>Solo Battle Royale: las bolas pueden golpearse entre sí.</small></span>
                <span className="toggle-field compact">
                  <input
                    id="createCollisionsEnabled" type="checkbox" role="switch" disabled={!battle}
                    checked={cfg.collisionsEnabled} onChange={(e) => patch({ collisionsEnabled: e.target.checked })}
                  />
                  <i />
                </span>
              </label>
            </div>
          </section>
        </div>

        <footer className="config-modal-actions">
          <span id="configLiveStatus" className="config-live" aria-live="polite">{liveStatus}</span>
          <button id="resetMatchConfigBtn" className="secondary-button" type="button" onClick={reset}>
            <svg className="ico" aria-hidden="true"><use href="#i-refresh" /></svg>RESTABLECER
          </button>
          <button id="saveMatchConfigBtn" className="submit-button" type="button" onClick={() => { setLiveStatus('Configuración actualizada.'); sessionStore.closeModal('matchConfig'); }}>
            <svg className="ico" aria-hidden="true"><use href="#i-check" /></svg>GUARDAR CONFIGURACIÓN
          </button>
        </footer>
      </div>
    </section>
  );
}
