import { useEffect, useRef, useState } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';
import { colorFor, suggestName } from '../../bridge/createConfig';
import { NET_CONFIG } from '../../game/net/netConfig';
import { ClientEnv } from '../../game/net/clientEnv';
import { CreateScreen } from './CreateScreen';
import { BrowserScreen } from './BrowserScreen';

function PreflightScreen() {
  const snap = useSession();
  const active = snap.screen === 'preflight';
  const p = snap.preflight;
  const rows: Array<[keyof typeof p.rows, string]> = [
    ['config', 'Configuración cliente/host'],
    ['relay', 'Relay público'],
    ['protocol', 'Compatibilidad de protocolo'],
    ['lobby', 'Directorio de partidas'],
  ];
  return (
    <section id="screenPreflight" className={`menu-screen preflight-screen${active ? ' active' : ''}`}>
      <div className="preflight-card">
        <div className="preflight-top">
          <div className="preflight-orb"><i /><i /><i /></div>
          <div>
            <span className="kicker">COMPROBACIÓN DE CONEXIÓN</span>
            <h2>Preparando multijugador</h2>
            <p id="preflightStatusText">{p.statusText}</p>
          </div>
        </div>
        <div className="preflight-grid">
          {rows.map(([key, label]) => (
            <div key={key} className="preflight-row" data-state={p.rows[key].state}>
              <i className="prow-icon" /><span>{label}</span><strong>{p.rows[key].text}</strong>
            </div>
          ))}
        </div>
        <div className="preflight-actions">
          <button id="preflightRetryBtn" className="secondary-button" type="button" disabled={p.running} onClick={() => void sessionStore.runPreflight()}>
            <svg className="ico" aria-hidden="true"><use href="#i-refresh" /></svg>REINTENTAR
          </button>
          <button id="preflightOfflineBtn" className={`submit-button${p.showOffline ? '' : ' hidden'}`} type="button" onClick={() => sessionStore.playOffline()}>
            <svg className="ico" aria-hidden="true"><use href="#i-play" /></svg>JUGAR OFFLINE
          </button>
          <button id="preflightMenuBtn" className={`secondary-button${p.showMenu ? '' : ' hidden'}`} type="button" onClick={() => sessionStore.showScreen('main')}>
            CONTINUAR AL MENÚ
          </button>
        </div>
        <small className="preflight-note">Si el relay falla, Crear, Unirse y Reconectar permanecen bloqueados. Offline nunca depende de la red.</small>
      </div>
    </section>
  );
}

function MainScreen() {
  const snap = useSession();
  const active = snap.screen === 'main';
  return (
    <section id="screenMain" className={`menu-screen main-screen${active ? ' active' : ''}`}>
      <div className="hero-actions">
        <button id="playOfflineBtn" className="menu-action primary" type="button" onClick={() => sessionStore.playOffline()}>
          <span className="action-icon"><svg className="ico" aria-hidden="true"><use href="#i-play" /></svg></span>
          <span className="action-text"><strong>JUGAR</strong><small>Partida offline instantánea · sin red</small></span>
          <span className="action-arrow" aria-hidden="true">→</span>
        </button>
        <button
          id="onlineBtn" className="menu-action" type="button"
          disabled={!snap.onlineAvailable}
          data-network={snap.onlineAvailable ? 'online' : 'offline'}
          onClick={() => sessionStore.openOnline()}
        >
          <span className="action-icon"><svg className="ico" aria-hidden="true"><use href="#i-globe" /></svg></span>
          <span className="action-text">
            <strong>ONLINE</strong>
            <small>
              {snap.onlineAvailable
                ? `Relay disponible · crear, unirse y reconectar · hasta ${(NET_CONFIG as any).maxPlayers} jugadores`
                : 'Multiplayer deshabilitado · relay no disponible'}
            </small>
          </span>
          <span className="action-arrow" aria-hidden="true">→</span>
        </button>
        <button
          id="reconnectBtn"
          className={`menu-action reconnect${snap.reconnectOffer ? '' : ' hidden'}`}
          type="button" disabled={!snap.reconnectOffer}
          onClick={() => void sessionStore.reconnectLast()}
        >
          <span className="action-icon"><svg className="ico" aria-hidden="true"><use href="#i-refresh" /></svg></span>
          <span className="action-text">
            <strong>RECONECTAR</strong>
            <small id="reconnectLabel">{snap.reconnectOffer ? `${snap.reconnectOffer.lobbyName} · reservar tu sitio en el relay` : 'Última partida'}</small>
          </span>
          <span className="action-arrow" aria-hidden="true">→</span>
        </button>
      </div>
    </section>
  );
}

function OnlineScreen() {
  const snap = useSession();
  const active = snap.screen === 'online';
  const source = (ClientEnv as any)?.source === 'config' ? 'config.json cargado' : 'config.json no disponible';
  const latency = Number.isFinite(snap.preflight.rtt as number) && (snap.preflight.rtt as number) > 0 ? ` · ${snap.preflight.rtt} ms` : '';
  return (
    <section id="screenOnline" className={`menu-screen${active ? ' active' : ''}`}>
      <div className="screen-toolbar">
        <button className="back-button" type="button" aria-label="Volver" onClick={() => sessionStore.showScreen('main')}>
          <svg className="ico" aria-hidden="true"><use href="#i-back" /></svg>
        </button>
        <div><span className="kicker">MULTIJUGADOR</span><h2>Jugar online</h2></div>
      </div>
      <div className="online-grid">
        <button id="createMatchBtn" className="feature-card" type="button" onClick={() => sessionStore.openCreate()}>
          <span className="feature-glyph"><svg className="ico" aria-hidden="true"><use href="#i-plus" /></svg></span>
          <strong>Crear partida</strong>
          <small>Tu navegador será el host autoritativo de física y puntuación.</small>
        </button>
        <button id="browseMatchBtn" className="feature-card" type="button" onClick={() => sessionStore.openBrowser()}>
          <span className="feature-glyph"><svg className="ico" aria-hidden="true"><use href="#i-search" /></svg></span>
          <strong>Unirse</strong>
          <small>Explora las salas publicadas por el relay, con ping medido en vivo.</small>
        </button>
      </div>
      <div id="onlineConfigStatus" className="online-config-card" data-state={snap.onlineAvailable ? 'online' : 'offline'}>
        <strong><svg className="ico" aria-hidden="true"><use href="#i-shield" /></svg>CONFIGURACIÓN DE RED</strong>
        <span>
          {snap.onlineAvailable
            ? `Relay conectado${latency} · ${source}. Los parámetros de cliente/host se leen del archivo, no de la interfaz.`
            : `Relay pendiente o no disponible · ${source}. Crear, Unirse y Reconectar quedan bloqueados hasta que el preflight pase.`}
        </span>
      </div>
    </section>
  );
}

function ProfileScreen() {
  const snap = useSession();
  const active = snap.screen === 'profile';
  const [value, setValue] = useState(snap.username);
  const inputRef = useRef<HTMLInputElement>(null);

  // Al entrar en la pantalla se sincroniza con el perfil y se enfoca el campo.
  useEffect(() => {
    if (active) {
      setValue(sessionStore.getSnapshot().username);
      const t = window.setTimeout(() => inputRef.current?.focus(), 30);
      return () => window.clearTimeout(t);
    }
  }, [active]);

  const name = value.trim() || 'Jugador';
  return (
    <section id="screenProfile" className={`menu-screen profile-screen${active ? ' active' : ''}`}>
      <div className="screen-toolbar">
        <button className="back-button" type="button" aria-label="Volver" onClick={() => sessionStore.showScreen('main')}>
          <svg className="ico" aria-hidden="true"><use href="#i-back" /></svg>
        </button>
        <div><span className="kicker">IDENTIDAD</span><h2>Tu perfil</h2></div>
      </div>
      <form
        id="profileForm" className="profile-layout"
        onSubmit={(event) => { event.preventDefault(); sessionStore.saveProfile(value); }}
      >
        <div className="profile-preview">
          <span id="profilePreviewDot" className="profile-avatar xl" style={{ background: colorFor(name) }}>
            <b id="profilePreviewInitial">{(name[0] || 'J').toUpperCase()}</b>
          </span>
          <strong id="profilePreviewName">{name}</strong>
          <small>Así te verán en el marcador y sobre tu bola.</small>
        </div>
        <div className="profile-form">
          <label className="field">
            <span>Nombre de jugador</span>
            <input
              id="usernameInput" ref={inputRef} maxLength={24} autoComplete="nickname"
              placeholder="Tu nombre" required value={value}
              onChange={(event) => setValue(event.target.value)}
            />
            <div className="field-foot">
              <small>Se guarda solo en este navegador. Puedes cambiarlo cuando quieras.</small>
              <small id="nameCounter" className="counter">{value.length}/{(NET_CONFIG as any).maxNameLength}</small>
            </div>
          </label>
          <div className="profile-actions">
            <button id="randomNameBtn" className="secondary-button" type="button" onClick={() => { const n = suggestName(); setValue(n); inputRef.current?.focus(); }}>
              <svg className="ico" aria-hidden="true"><use href="#i-dice" /></svg>SUGERIR
            </button>
            <button className="submit-button" type="submit"><svg className="ico" aria-hidden="true"><use href="#i-check" /></svg>GUARDAR PERFIL</button>
          </div>
        </div>
      </form>
    </section>
  );
}

function JoiningScreen() {
  const snap = useSession();
  const active = snap.screen === 'joining';
  const { title, value, text } = snap.joining;
  // Umbrales alineados con los `progress` que emite MultiplayerSession.
  const thresholds: Array<[string, string, number]> = [
    ['relay', 'Relay', 0.28], ['lobby', 'Sala', 0.5], ['p2p', 'P2P', 0.78], ['world', 'Mundo', 1],
  ];
  let activeAssigned = false;
  return (
    <section id="screenJoining" className={`menu-screen joining-screen${active ? ' active' : ''}`}>
      <div className="joining-orb"><i /><i /><i /></div>
      <span className="kicker">CONEXIÓN MULTIJUGADOR</span>
      <h2 id="joinTitle">{title}</h2>
      <p id="joinStatus">{text}</p>
      <div className="join-progress"><i id="joinProgressBar" style={{ width: `${value * 100}%` }} /></div>
      <ol id="joinSteps" className="join-steps">
        {thresholds.map(([step, label, threshold]) => {
          const done = value >= threshold;
          let state = 'todo';
          if (done) state = 'done';
          else if (!activeAssigned) { state = 'active'; activeAssigned = true; }
          return <li key={step} data-step={step} data-state={state}><i /><span>{label}</span></li>;
        })}
      </ol>
      <button id="cancelJoinBtn" className="secondary-button" type="button" onClick={() => void sessionStore.cancelJoin()}>Cancelar</button>
    </section>
  );
}

export function MenuRoot() {
  const snap = useSession();
  const username = snap.username || 'Sin nombre';
  return (
    <section id="frontEnd" className={`front-end${snap.menuVisible ? '' : ' hidden'}`} aria-label="Menú principal">
      <div className="menu-backdrop" aria-hidden="true"><i className="orb orb-a" /><i className="orb orb-b" /><i className="orb orb-c" /></div>
      <div className="menu-shell">
        <header className="menu-header">
          <div className="game-mark" aria-hidden="true"><i /></div>
          <div className="menu-title">
            <span className="kicker">PROCEDURAL ARCADE GOLF</span>
            <h1>NOISE <b>GOLF</b> 2D</h1>
            <p>Campos imposibles, física limpia y partidas P2P de hasta 16 jugadores.</p>
          </div>
          <div className="menu-header-side">
            <div id="relayPill" className="relay-pill" data-state={snap.relayPill.state}>
              <i /><span id="relayPillText">{snap.relayPill.text}</span>
            </div>
            <button id="profileButton" className="profile-chip" type="button" onClick={() => sessionStore.showScreen('profile')}>
              <span id="profileDot" className="profile-avatar" style={{ background: colorFor(username) }}>
                <b id="profileInitial">{(username.trim()[0] || 'J').toUpperCase()}</b>
              </span>
              <span className="profile-chip-text"><strong id="profileName">{username}</strong><small>Editar perfil</small></span>
            </button>
          </div>
        </header>

        <div id="menuNotice" className={`menu-notice${snap.notice ? '' : ' hidden'}`} data-tone={snap.notice?.tone || 'neutral'}>
          {snap.notice?.text || ''}
        </div>

        <PreflightScreen />
        <MainScreen />
        <OnlineScreen />
        <CreateScreen />
        <BrowserScreen />
        <ProfileScreen />
        <JoiningScreen />
      </div>
    </section>
  );
}
