// Fachada del "island" imperativo: posee el ciclo de vida de GolfGame y del
// arranque (ClientEnv → NET_CONFIG → juego). React lo invoca desde un efecto.
// @ts-nocheck
import { ClientEnv } from '../game/net/clientEnv';
import { ApplyClientEnvConfig } from '../game/net/netConfig';
import { GolfGame } from '../game/golfGame';
import { HUD } from '../game/hud';
import { PlayerProfile } from '../game/net/profile';

class GameHost {
  // Declaraciones para que los consumidores tipados (sessionStore) vean las
  // propiedades pese al @ts-nocheck interno.
  game: any;
  hud: any;
  profile: any;
  booted: boolean;
  bootEpoch: number;
  unloadHandlers: Array<[string, () => void]>;
  stats: { gamesCreated: number; gamesDestroyed: number };

  constructor() {
    this.game = null;
    this.hud = null;
    this.profile = null;
    this.booted = false;
    this.bootEpoch = 0;
    this.unloadHandlers = [];
    // Instrumentación para tests de StrictMode/HMR.
    this.stats = { gamesCreated: 0, gamesDestroyed: 0 };
  }

  get activeRafLoops() {
    return this.game && this.game.rafId != null ? 1 : 0;
  }

  async boot(canvas) {
    if (this.booted) throw new Error('GameHost.boot() llamado dos veces sin destroy().');
    this.booted = true;
    // Época de arranque: si destroy() llega mientras esperamos config.json
    // (doble montaje de StrictMode), este boot se cancela sin crear nada.
    const myEpoch = ++this.bootEpoch;

    // Contrato temporal intacto: config.json → NET_CONFIG → construir juego.
    await ClientEnv.ready;
    if (myEpoch !== this.bootEpoch) return null;
    ApplyClientEnvConfig();

    this.hud = new HUD();
    this.hud.attach(document);
    this.game = new GolfGame(canvas, this.hud).init();
    this.stats.gamesCreated++;
    this.profile = this.profile || new PlayerProfile();
    this.game.start();

    const onUnload = () => {
      try { this.game?.networkSession?.disconnectForUnload?.(); } catch (_) { /* noop */ }
    };
    window.addEventListener('pagehide', onUnload);
    window.addEventListener('beforeunload', onUnload);
    this.unloadHandlers.push(['pagehide', onUnload], ['beforeunload', onUnload]);

    // Asas de depuración/E2E (sustituyen a window.__noiseGolf* del main clásico).
    window.__noiseGolf = this.game;
    window.__noiseGolfProfile = this.profile;
    window.__noiseGolfHost = this;
    window.__noiseGolfStats = this.statsView();
    window.__noiseGolfReady = true;
    return this.game;
  }

  statsView() {
    const self = this;
    return {
      get gamesCreated() { return self.stats.gamesCreated; },
      get gamesDestroyed() { return self.stats.gamesDestroyed; },
      get activeRafLoops() { return self.activeRafLoops; },
    };
  }

  destroy() {
    this.bootEpoch++; // cancela cualquier boot() aún esperando config.json
    if (this.game) {
      this.game.destroy();
      this.stats.gamesDestroyed++;
    }
    this.game = null;
    for (const [type, fn] of this.unloadHandlers) window.removeEventListener(type, fn);
    this.unloadHandlers.length = 0;
    this.booted = false;
    window.__noiseGolfReady = false;
  }
}

export const gameHost = new GameHost();
