import { useEffect, useMemo, useState } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';
import {
  CreateConfigState, initialCreateConfig, summaryTexts, toMatchSettings,
} from '../../bridge/createConfig';
import { MatchConfigPanel } from './MatchConfigPanel';

export function CreateScreen() {
  const snap = useSession();
  const active = snap.screen === 'create';
  const [cfg, setCfg] = useState<CreateConfigState>(() => initialCreateConfig(snap.username));
  const [liveStatus, setLiveStatus] = useState('');

  // Paridad con el legacy: cada vez que se entra a "crear", el nombre de la
  // sala vuelve al valor por defecto derivado del perfil.
  useEffect(() => {
    if (active) setCfg((prev) => ({ ...prev, name: `${snap.username || 'Jugador'} · Campo` }));
  }, [active, snap.username]);

  const summary = useMemo(() => summaryTexts(cfg, snap.username), [cfg, snap.username]);
  const patch = (p: Partial<CreateConfigState>) => setCfg((prev) => ({ ...prev, ...p }));

  return (
    <section id="screenCreate" className={`menu-screen create-screen${active ? ' active' : ''}`}>
      <div className="screen-toolbar">
        <button className="back-button" type="button" aria-label="Volver" onClick={() => sessionStore.showScreen('online')}>
          <svg className="ico" aria-hidden="true"><use href="#i-back" /></svg>
        </button>
        <div><span className="kicker">NUEVA SALA</span><h2>Crear partida</h2></div>
      </div>
      <form
        id="createForm" className="create-layout"
        onSubmit={(event) => {
          event.preventDefault();
          void sessionStore.createMatch(toMatchSettings(cfg, snap.username));
        }}
      >
        <div className="create-main">
          <div className="form-grid">
            <label className="field span-2">
              <span>Nombre de la partida</span>
              <input id="createName" maxLength={40} required value={cfg.name} onChange={(e) => patch({ name: e.target.value })} />
            </label>
            <label className="field span-2">
              <span>Contraseña <em>opcional</em></span>
              <input
                id="createPassword" type="password" maxLength={72} autoComplete="new-password"
                placeholder="Sin contraseña · sala pública"
                value={cfg.password} onChange={(e) => patch({ password: e.target.value })}
              />
            </label>
            <button
              id="openMatchConfigBtn" className="match-config-trigger span-2" type="button"
              aria-haspopup="dialog" aria-controls="matchConfigPanel"
              aria-expanded={snap.modals.includes('matchConfig')}
              onClick={() => sessionStore.openModal('matchConfig')}
            >
              <span className="match-config-glyph"><svg className="ico" aria-hidden="true"><use href="#i-settings" /></svg></span>
              <span><strong>CONFIGURAR PARTIDA</strong><small id="configTriggerSummary">{summary.trigger}</small></span>
              <svg className="ico match-config-arrow" aria-hidden="true"><use href="#i-chevron" /></svg>
            </button>
          </div>
        </div>

        <aside className="create-summary" aria-label="Resumen de la sala">
          <span className="kicker">RESUMEN</span>
          <h3 id="summaryName">{summary.name}</h3>
          <ul className="summary-list">
            <li><svg className="ico" aria-hidden="true"><use href="#i-turns" /></svg><span>Modo</span><strong id="summaryMode">{summary.mode}</strong></li>
            <li><svg className="ico" aria-hidden="true"><use href="#i-users" /></svg><span>Jugadores</span><strong id="summaryPlayers">{summary.players}</strong></li>
            <li><svg className="ico" aria-hidden="true"><use href="#i-trophy" /></svg><span>Meta</span><strong id="summaryPoints">{summary.points}</strong></li>
            <li><svg className="ico" aria-hidden="true"><use href="#i-clock" /></svg><span>Ritmo</span><strong id="summaryTiming">{summary.timing}</strong></li>
            <li><svg className="ico" aria-hidden="true"><use href="#i-globe" /></svg><span>Ambientes</span><strong id="summaryWorlds">{summary.worlds}</strong></li>
            <li><svg className="ico" aria-hidden="true"><use href="#i-lock" /></svg><span>Acceso</span><strong id="summaryAccess">{summary.access}</strong></li>
          </ul>
          <p id="summaryHint" className="summary-hint">{summary.hint}</p>
          <button className="submit-button block" type="submit"><svg className="ico" aria-hidden="true"><use href="#i-play" /></svg>CREAR Y ENTRAR</button>
        </aside>
      </form>

      <MatchConfigPanel cfg={cfg} patch={patch} liveStatus={liveStatus} setLiveStatus={setLiveStatus} />
    </section>
  );
}
