import { sessionStore, useSession } from '../../bridge/sessionStore';

/**
 * Ventana de reconexión: muestra cuánto queda de la reserva que el host
 * mantiene abierta. Mientras está activa, el bloqueo de entrada lo aplica el
 * store (estado derivado), no este componente.
 */
export function ReconnectPanel() {
  const snap = useSession();
  const status = snap.net.reconnect;
  const open = !!status?.active;

  const remaining = Math.max(0, Number(status?.remainingMs) || 0);
  const total = Math.max(1, Number(status?.totalMs) || 1);
  const seconds = Math.ceil(remaining / 1000);
  const countdown = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
  const attempts = status?.busy ? `Intento ${status.attempts}…` : `Intento ${Math.max(1, status?.attempts || 1)}`;

  return (
    <section
      id="reconnectPanel"
      className={`mini-modal reconnect-modal${open ? '' : ' hidden'}`}
      role="dialog" aria-modal="true" aria-labelledby="reconnectTitle"
    >
      <div className="mini-modal-card reconnect-card">
        <span className="kicker">CONEXIÓN PERDIDA</span>
        <h2 id="reconnectTitle">{status?.lobbyName ? `Recuperando “${status.lobbyName}”…` : 'Recuperando la partida…'}</h2>
        <p id="reconnectCopy" className="modal-copy">Tu plaza, tu puntuación y tu bola siguen reservadas en el host mientras dure la cuenta atrás.</p>
        <div className="reconnect-meter">
          <div className="reconnect-meter-head">
            <strong id="reconnectCountdown">{countdown}</strong>
            <span id="reconnectAttempts">{attempts}</span>
          </div>
          <div className="reconnect-bar"><i id="reconnectBar" style={{ width: `${Math.max(0, Math.min(100, (remaining / total) * 100))}%` }} /></div>
        </div>
        <p id="reconnectDetail" className="reconnect-detail" aria-live="polite" data-tone={status?.lastError ? 'bad' : 'neutral'}>
          {status?.lastError || 'Reintentando contra el relay y el host…'}
        </p>
        <div className="modal-actions center">
          <button id="reconnectNowBtn" className="submit-button" type="button" onClick={() => sessionStore.reconnectNow()}>REINTENTAR AHORA</button>
          <button id="reconnectLeaveBtn" className="secondary-button danger-outline" type="button" onClick={() => sessionStore.reconnectLeave()}>ABANDONAR</button>
        </div>
      </div>
    </section>
  );
}
