// Clasificación de calidad de red por RTT. Extraída de networkHud para que
// la UI React y el HUD compartan una única fuente.
export interface NetQuality {
  bars: 0 | 1 | 2 | 3 | 4;
  label: string;
  key: 'none' | 'great' | 'good' | 'fair' | 'bad';
}

export function quality(rtt: number | null | undefined): NetQuality {
  if (!Number.isFinite(rtt as number) || (rtt as number) <= 0) return { bars: 0, label: '—', key: 'none' };
  const value = rtt as number;
  if (value <= 60) return { bars: 4, label: 'Excelente', key: 'great' };
  if (value <= 120) return { bars: 3, label: 'Buena', key: 'good' };
  if (value <= 220) return { bars: 2, label: 'Media', key: 'fair' };
  return { bars: 1, label: 'Débil', key: 'bad' };
}
