// @ts-nocheck
// Arranque de la aplicación: GameHost (island imperativo) + SessionStore.
// F3 vive aquí porque es un atajo global de ventana, no de un componente.
import { gameHost } from './GameHost';
import { sessionStore } from './sessionStore';

let booted = false;
let cleanups = [];

function hideBootScreen() {
  const boot = document.querySelector('#bootScreen');
  if (!boot) return;
  boot.classList.add('hidden');
  window.setTimeout(() => boot.remove(), 600);
}

export function bootApp() {
  if (booted) return;
  booted = true;
  (async () => {
    try {
      const canvas = document.querySelector('#game');
      const game = await gameHost.boot(canvas);
      if (!game) return; // boot cancelado por un destroy() intermedio (StrictMode)
      sessionStore.init();

      const onExit = () => sessionStore.handlePageExit();
      window.addEventListener('pagehide', onExit);
      window.addEventListener('beforeunload', onExit);
      const onF3 = (event) => {
        if (event.key === 'F3') { event.preventDefault(); sessionStore.toggleMetrics(); }
      };
      window.addEventListener('keydown', onF3);
      cleanups.push(
        () => window.removeEventListener('pagehide', onExit),
        () => window.removeEventListener('beforeunload', onExit),
        () => window.removeEventListener('keydown', onF3),
      );

      window.__noiseGolfStore = sessionStore;
      window.setTimeout(hideBootScreen, 260);
    } catch (error) {
      console.error('[Noise Golf 2D] Error de arranque:', error);
      hideBootScreen();
      const detail = document.querySelector('#bootErrorDetail');
      document.querySelector('#bootError')?.classList.remove('hidden');
      if (detail) detail.textContent = error?.message || String(error);
      window.__noiseGolfReady = false;
    }
  })();
}

export function destroyApp() {
  for (const fn of cleanups) fn();
  cleanups = [];
  sessionStore.destroy();
  gameHost.destroy();
  booted = false;
}
