import { useEffect, useState } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';
import { formatInt } from '../../bridge/createConfig';
import type { StandingRow } from '../../bridge/types';

export function MatchOverPanel() {
  const { net } = useSession();
  const payload = net.matchOver;
  const [dismissed, setDismissed] = useState(false);

  // Un nuevo fin de partida (u otra partida) reinicia el descarte local.
  useEffect(() => { setDismissed(false); }, [payload]);

  const rows: StandingRow[] = payload?.standings?.length ? payload.standings : net.standings;
  const winner = rows.find((p) => p.playerKey === payload?.winnerPlayerKey) || rows[0];
  const localWon = !!winner?.local;
  const open = !!payload && !dismissed;

  return (
    <section id="matchOverPanel" className={`overlay-panel${open ? '' : ' hidden'}`} aria-modal="true">
      <div className="matchover-card">
        <div className="matchover-crown"><svg className="ico" aria-hidden="true"><use href="#i-trophy" /></svg></div>
        <span className="kicker">PARTIDA TERMINADA</span>
        <h1 id="matchOverTitle">{localWon ? '¡Has ganado!' : (winner ? `Gana ${winner.username}` : 'Partida terminada')}</h1>
        <p id="matchOverSub" className="modal-copy">
          {winner ? `${formatInt(winner.points)} puntos alcanzados. Marcador final de la sala.` : 'Marcador final de la sala.'}
        </p>
        <div className="matchover-table">
          <div className="matchover-head"><span>#</span><span>JUGADOR</span><span>GOLPES</span><span>PUNTOS</span></div>
          <div id="matchOverRows" className="matchover-rows">
            {rows.map((row) => (
              <div
                key={row.playerKey}
                className={`matchover-row${row.playerKey === winner?.playerKey ? ' is-winner' : ''}${row.local ? ' is-local' : ''}`}
              >
                <span className="row-rank">{row.rank}</span>
                <div className="row-id">
                  <i className="player-color" style={{ background: row.color, color: row.color }} />
                  <span className="player-name">{row.username}</span>
                </div>
                <span className="row-metric">{row.strokes}g</span>
                <strong className="row-points">{formatInt(row.points)}</strong>
              </div>
            ))}
          </div>
        </div>
        <div className="modal-actions center">
          <button id="matchOverStay" className="secondary-button" type="button" onClick={() => setDismissed(true)}>SEGUIR VIENDO</button>
          <button id="matchOverHome" className="submit-button" type="button" onClick={() => { setDismissed(true); void sessionStore.leaveOnline(); }}>VOLVER AL INICIO</button>
        </div>
      </div>
    </section>
  );
}
