// Store externo (useSyncExternalStore) que sustituye al MenuController legacy.
// Toda la verdad de la UI vive aquí como estado inmutable; el island imperativo
// (GolfGame + MultiplayerSession) se consume a través de acciones y de un
// sondeo a 4 Hz. Nada de esto corre dentro del bucle de 60 Hz.
import { useSyncExternalStore } from 'react';
import { ClientEnv } from '../game/net/clientEnv';
import { NET_CONFIG } from '../game/net/netConfig';
import { RelayClient } from '../game/net/relayClient';
import { MultiplayerSession } from '../game/net/multiplayerSession';
import { gameHost } from './GameHost';
import { formatRemaining } from './createConfig';
import type {
  ISession, Lobby, MatchSettings, MapVoteStatus, PreflightRowState,
  ReconnectStatus, RelayPillState, Screen, StandingRow, Tone,
} from './types';

export type ModalId = 'gameMenu' | 'matchConfig' | 'joinPassword' | 'mapVote' | 'reconnect';

export interface PreflightState {
  running: boolean;
  statusText: string;
  rows: Record<'config' | 'relay' | 'protocol' | 'lobby', { state: PreflightRowState; text: string }>;
  showOffline: boolean;
  showMenu: boolean;
  rtt: number | null;
}

export interface Snapshot {
  screen: Screen;
  menuVisible: boolean;
  metricsOpen: boolean;
  modals: ModalId[];
  notice: { text: string; tone: Tone } | null;
  username: string;
  onlineAvailable: boolean;
  relayPill: { state: RelayPillState; text: string };
  preflight: PreflightState;
  reconnectOffer: { lobbyName: string } | null;
  browser: {
    servers: Lobby[];
    pings: Record<string, number>;
    refreshing: boolean;
    countdown: number;
    query: string;
    modeFilter: 'all' | 'turn' | 'battle';
    hideFull: boolean;
    sort: 'ping' | 'players' | 'name' | 'status';
  };
  joining: { title: string; value: number; text: string };
  passwordLobby: Lobby | null;
  net: {
    online: boolean;
    role: 'host' | 'client' | 'offline';
    spectator: boolean;
    runtimeLabel: string;
    status: any;
    standings: StandingRow[];
    netStats: any;
    pingHistory: number[];
    reconnect: ReconnectStatus | null;
    mapVote: MapVoteStatus | null;
    matchOver: any;
    localPlayerKey: string | null;
  };
}

const OFFLINE_NET: Snapshot['net'] = {
  online: false, role: 'offline', spectator: false,
  runtimeLabel: 'EXPEDICIÓN PROCEDURAL · OFFLINE',
  status: null, standings: [], netStats: null, pingHistory: [], reconnect: null,
  mapVote: null, matchOver: null, localPlayerKey: null,
};

const initialSnapshot = (): Snapshot => ({
  screen: 'preflight',
  menuVisible: true,
  metricsOpen: false,
  modals: [],
  notice: null,
  username: '',
  onlineAvailable: false,
  relayPill: { state: 'idle', text: 'Relay sin comprobar' },
  preflight: {
    running: false,
    statusText: 'Se comprueba config.json, el relay público y el protocolo antes de habilitar Online.',
    rows: {
      config: { state: 'idle', text: 'PENDIENTE' },
      relay: { state: 'idle', text: 'PENDIENTE' },
      protocol: { state: 'idle', text: 'PENDIENTE' },
      lobby: { state: 'idle', text: 'PENDIENTE' },
    },
    showOffline: false,
    showMenu: false,
    rtt: null,
  },
  reconnectOffer: null,
  browser: {
    servers: [], pings: {}, refreshing: false, countdown: 0,
    query: '', modeFilter: 'all', hideFull: false, sort: 'ping',
  },
  joining: { title: 'Conectando…', value: 0, text: 'Conectando…' },
  passwordLobby: null,
  net: OFFLINE_NET,
});

class SessionStore {
  snap: Snapshot = initialSnapshot();
  private listeners = new Set<() => void>();
  private session: ISession | null = null;
  private unsubs: Array<() => void> = [];
  private pollId = 0;
  private browserTick = 0;
  private preflightLobbyIds = new Set<string>();
  private unloadHandled = false;
  pollsStarted = 0; // instrumentación

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  };

  getSnapshot = () => this.snap;

  private set(patch: Partial<Snapshot>) {
    this.snap = { ...this.snap, ...patch };
    this.applyInputLock();
    for (const fn of this.listeners) fn();
  }

  private patchNet(patch: Partial<Snapshot['net']>) {
    this.set({ net: { ...this.snap.net, ...patch } });
  }

  // Bloqueo de entrada derivado: sustituye a las 9 lecturas legacy de
  // classList.contains('hidden') como fuente de verdad.
  private applyInputLock() {
    const s = this.snap;
    const locked = s.menuVisible || s.modals.includes('gameMenu') || !!s.net.reconnect?.active;
    gameHost.game?.setInputLocked(locked);
  }

  private get profile() { return gameHost.profile; }
  private get game() { return gameHost.game; }
  private get hud() { return gameHost.game?.hud; }

  /* ── Ciclo de vida ──────────────────────────────────────────────────── */

  init() {
    this.set({ username: this.profile?.username || '' });
    this.setOfflineHud();
    this.startPoll();

    if (this.profile?.username) {
      void this.runPreflight({ initial: true });
    } else {
      this.set({ screen: 'profile', relayPill: { state: 'idle', text: 'Relay sin comprobar' } });
    }
  }

  destroy() {
    if (this.pollId) window.clearInterval(this.pollId);
    this.pollId = 0;
    for (const u of this.unsubs) u();
    this.unsubs = [];
    this.session = null;
    this.snap = initialSnapshot();
  }

  private startPoll() {
    if (this.pollId) window.clearInterval(this.pollId);
    this.pollsStarted++;
    // Latido de interfaz a 4 Hz (heredero del setInterval(menu.update, 250)).
    this.pollId = window.setInterval(() => this.pollTick(), 250);
  }

  private pollTick() {
    const s = this.session;
    if (s && s.getStatus?.().online) {
      const status = s.getStatus();
      const standings = s.getStandings();
      const netStats = s.getNetStats?.() || null;
      const reconnect = s.getReconnectStatus();
      const mapVote = s.getMapVoteStatus();
      const prev = this.snap.net;

      // Historial de ping para la gráfica de métricas (60 muestras).
      let pingHistory = prev.pingHistory;
      if (netStats && Number.isFinite(netStats.ping)) {
        pingHistory = [...prev.pingHistory, netStats.ping].slice(-60);
      }

      // El fin de partida se limpia cuando el estado del host lo retira.
      const matchOver = status.matchOver ? prev.matchOver : null;

      // Publicación ≤4 Hz: los objetos se rehacen en cada lectura, así que la
      // igualdad se decide por contenido serializado.
      const next = { status, standings, netStats, reconnect, mapVote, pingHistory, matchOver };
      const changed = JSON.stringify(next) !== JSON.stringify({
        status: prev.status, standings: prev.standings, netStats: prev.netStats,
        reconnect: prev.reconnect, mapVote: prev.mapVote, pingHistory: prev.pingHistory,
        matchOver: prev.matchOver,
      });
      if (changed) this.patchNet(next);
    }
    // Cuenta atrás del navegador de salas.
    if (this.snap.screen === 'browser') this.browserCountdownTick();
  }

  toggleMetrics() { this.set({ metricsOpen: !this.snap.metricsOpen }); }
  closeMetrics() { this.set({ metricsOpen: false }); }

  /* ── Sesión ─────────────────────────────────────────────────────────── */

  private prepareSession(): ISession {
    if (this.session) {
      const s: any = this.session;
      if (s.role !== 'offline' && s.lobby?.id && s.signaling?.connected) {
        try { s.signaling.send('lobby:leave', { lobbyId: s.lobby.id }); } catch (_) { /* noop */ }
        try { this.profile.clearLastSession(); } catch (_) { /* noop */ }
      }
      try { s.relay.close(true); } catch (_) { /* noop */ }
      try { s.transport?.close(); } catch (_) { /* noop */ }
      for (const u of this.unsubs) u();
      this.unsubs = [];
    }
    const session = new (MultiplayerSession as any)(this.game, this.profile) as ISession;
    this.session = session;
    this.wireSession(session);
    return session;
  }

  private ensureSession(): ISession {
    if (!this.session) {
      const session = new (MultiplayerSession as any)(this.game, this.profile) as ISession;
      this.session = session;
      this.wireSession(session);
    }
    return this.session;
  }

  private wireSession(session: ISession) {
    const on = (type: string, fn: (payload?: any) => void) => this.unsubs.push(session.on(type, fn));

    on('progress', ({ value, text }: any) => {
      this.set({ joining: { ...this.snap.joining, value: Math.max(0, Math.min(1, Number(value) || 0)), text: text || 'Conectando…' } });
    });
    on('error', (error: any) => this.showNotice(error?.message || String(error), 'bad'));
    on('ready', ({ spectator }: any = {}) => {
      this.game?.setNetworkSession(session);
      this.hud?.setRuntime('online');
      const role = (session as any).role === 'host' ? 'host' : 'client';
      this.set({
        menuVisible: false,
        modals: [],
        net: {
          ...this.snap.net,
          online: true,
          role,
          spectator: !!spectator,
          localPlayerKey: (session as any).localPlayerKey || null,
          runtimeLabel: spectator ? 'ONLINE · ESPECTADOR' : `ONLINE · ${role === 'host' ? 'HOST' : 'CLIENTE'}`,
          matchOver: null,
          pingHistory: [],
        },
      });
      this.updateReconnectOffer();
    });
    on('standings', (rows: StandingRow[]) => this.patchNet({ standings: rows || [] }));
    on('matchover', (payload: any) => this.patchNet({ matchOver: payload || null }));
    on('connection', ({ state, text }: any = {}) => {
      if (state === 'reconnecting' || state === 'degraded' || state === 'relay-disconnected') {
        this.hud?.flashStatus(text, 'neutral', 1.4);
      }
    });
    on('iceerror', () => this.hud?.flashStatus('ICE no pudo usar una ruta configurada', 'neutral', 1.2));
    on('reconnect', (status: ReconnectStatus) => this.patchNet({ reconnect: status?.active ? status : null }));
    on('rejected', ({ text }: any = {}) => {
      this.showNotice(text || 'El host rechazó la conexión.', 'bad');
      void this.leaveOnline();
    });
    on('closed', ({ reason, text }: any = {}) => {
      const message = text || (reason === 'host-timeout' ? 'El host no volvió a tiempo.' : 'El host cerró la partida.');
      this.showNotice(message, 'bad');
      void this.leaveOnline();
    });
    on('mapvote', () => {
      const s = this.session;
      this.patchNet({ mapVote: s?.getStatus().online ? s.getMapVoteStatus() : null });
    });
    on('gameevent', (event: any) => this.handleGameEvent(event));
  }

  private handleGameEvent(event: any) {
    const hud = this.hud;
    const session: any = this.session;
    if (!hud || !event) return;
    if (event.event === 'map-changed') hud.flashStatus('Mapa cambiado por votación unánime', 'good', 1.35);
    else if (event.event === 'next-hole') hud.flashStatus('Nuevo hoyo', 'good', 1.1);
    else if (event.event === 'finish-countdown') {
      hud.flashStatus(`${Math.round(event.seconds || 0)} s para que los demás lleguen`, 'penalty', 1.6);
    } else if (event.event === 'world:expired') {
      const text = event.reason === 'finish-countdown' ? 'Se acabó el tiempo restante' : 'Se acabó el tiempo del mundo';
      hud.flashStatus(`${text} · avanzando`, 'penalty', 1.5);
    } else if (event.event === 'penalty' && event.playerKey === session?.localPlayerKey) {
      const text = event.sabotageBy
        ? `Sabotaje de ${event.sabotageByUsername || 'otro jugador'} · vuelves al inicio · +${event.penalty || 1}`
        : `${event.reason || 'Penalización'} · +${event.penalty || 1}`;
      hud.flashStatus(text, 'penalty', event.sabotageBy ? 1.8 : 1.05);
    } else if (event.event === 'penalty' && event.sabotageBy === session?.localPlayerKey) {
      hud.flashStatus(`¡Sabotaje! ${event.sabotageVictimUsername || 'Otra bola'} vuelve al inicio`, 'good', 1.6);
    }
  }

  /* ── Avisos / HUD offline ───────────────────────────────────────────── */

  showNotice(text: string, tone: Tone = 'neutral') {
    this.set({ notice: text ? { text, tone } : null });
  }

  private setOfflineHud() {
    // MatchBar/NetChip derivan del snapshot (net.online=false ⇒ vista offline);
    // aquí solo queda el canal imperativo de body.dataset.
    this.hud?.setRuntime('offline');
  }

  /* ── Perfil ─────────────────────────────────────────────────────────── */

  saveProfile(username: string): boolean {
    try {
      this.profile.setUsername(username);
      this.set({ username: this.profile.username });
      this.showNotice('Perfil guardado en este navegador.', 'good');
      void this.runPreflight({ initial: true });
      return true;
    } catch (error: any) {
      this.showNotice(error.message, 'bad');
      return false;
    }
  }

  private requireProfile(): boolean {
    if (this.profile?.username) return true;
    this.showNotice('Elige un nombre de jugador antes de continuar.', 'neutral');
    this.set({ screen: 'profile' });
    return false;
  }

  /* ── Preflight ──────────────────────────────────────────────────────── */

  private setPreflight(patch: Partial<PreflightState>) {
    this.set({ preflight: { ...this.snap.preflight, ...patch } });
  }

  private setPreflightRow(row: keyof PreflightState['rows'], state: PreflightRowState, text: string) {
    this.setPreflight({ rows: { ...this.snap.preflight.rows, [row]: { state, text } } });
  }

  private setOnlineAvailability(available: boolean) {
    const rtt = this.snap.preflight.rtt;
    const relayPill: Snapshot['relayPill'] = available
      ? { state: 'ok', text: `Relay ${Number.isFinite(rtt as number) && (rtt as number) > 0 ? `${rtt} ms` : 'conectado'}` }
      : this.snap.preflight.running
        ? this.snap.relayPill
        : { state: 'fail', text: 'Relay no disponible' };
    this.set({ onlineAvailable: available, relayPill });
    this.updateReconnectOffer();
  }

  async runPreflight(options: { initial?: boolean } = {}) {
    if (!this.profile?.username || this.snap.preflight.running) return;
    this.preflightLobbyIds.clear();
    this.set({
      screen: 'preflight',
      notice: null,
      relayPill: { state: 'working', text: 'Comprobando relay…' },
      preflight: {
        running: true, rtt: null, showOffline: false, showMenu: false,
        statusText: 'Comprobando configuración y conexión con el relay…',
        rows: {
          config: { state: 'working', text: 'COMPROBANDO' },
          relay: { state: 'idle', text: 'PENDIENTE' },
          protocol: { state: 'idle', text: 'PENDIENTE' },
          lobby: { state: 'idle', text: 'PENDIENTE' },
        },
      },
      onlineAvailable: false,
    });

    const cfg: any = ClientEnv?.config || {};
    let probe: any = null;
    try {
      if ((ClientEnv as any)?.source !== 'config') throw new Error((ClientEnv as any)?.loadError || 'No se pudo cargar config.json.');
      if (!cfg.onlineEnabled) throw new Error('Multiplayer está desactivado en config.json.');
      if (!String(cfg.relayUrl || '').trim()) throw new Error('relayUrl no está configurado en config.json.');
      const relayUrl = this.profile.setRelayUrl(this.profile.getRelayUrl());
      this.setPreflightRow('config', 'ok', 'CONFIG OK');
      this.setPreflightRow('relay', 'working', 'CONECTANDO');

      probe = new (RelayClient as any)(this.profile);
      const welcome = await probe.connect(relayUrl, {
        autoReconnect: false,
        timeoutMs: Math.max(1500, Number(cfg.preflightTimeoutMs) || Number(cfg.relayConnectTimeoutMs) || 6500),
      });
      const rtt = Math.round(probe.lastRelayRtt || 0);
      this.setPreflight({ rtt });
      this.setPreflightRow('relay', 'ok', `${rtt} MS`);

      const protocol = Number(welcome?.protocolVersion ?? (NET_CONFIG as any).protocolVersion);
      if (protocol !== (NET_CONFIG as any).protocolVersion) {
        throw new Error(`Protocolo incompatible: relay ${protocol}, cliente ${(NET_CONFIG as any).protocolVersion}.`);
      }
      this.setPreflightRow('protocol', 'ok', `V${protocol} COMPATIBLE`);

      this.setPreflightRow('lobby', 'working', 'LEYENDO');
      const list = await probe.request('lobby:list', {});
      const lobbies = Array.isArray(list?.lobbies) ? list.lobbies : [];
      for (const lobby of lobbies) if (lobby?.id) this.preflightLobbyIds.add(String(lobby.id));
      this.setPreflightRow('lobby', 'ok', `${lobbies.length} SALAS`);

      this.setOnlineAvailability(true);
      this.refreshReconnectAgainstKnownLobbies();
      this.setPreflight({
        statusText: `Relay conectado correctamente${welcome?.relayName ? ` · ${welcome.relayName}` : ''}. Multiplayer habilitado.`,
        showMenu: true,
      });
      if (options.initial) window.setTimeout(() => {
        if (this.snap.screen === 'preflight') this.set({ screen: 'main' });
      }, 550);
    } catch (error: any) {
      this.setOnlineAvailability(false);
      const rows = { ...this.snap.preflight.rows };
      for (const key of Object.keys(rows) as Array<keyof PreflightState['rows']>) {
        if (['working', 'idle'].includes(rows[key].state)) rows[key] = { state: 'fail', text: 'NO DISPONIBLE' };
      }
      this.setPreflight({
        rows,
        statusText: `${error.message} Solo Offline está habilitado.`,
        showOffline: true,
        showMenu: true,
      });
      this.set({ relayPill: { state: 'fail', text: 'Relay no disponible' } });
    } finally {
      if (probe) probe.close(true);
      this.setPreflight({ running: false });
    }
  }

  /* ── Navegación / modales ───────────────────────────────────────────── */

  showScreen(screen: Screen) {
    const modals = this.snap.modals.filter((m) => m !== 'matchConfig');
    this.set({ screen, modals });
    if (screen !== 'browser') this.stopBrowserCountdown();
  }

  openModal(id: ModalId) {
    if (!this.snap.modals.includes(id)) this.set({ modals: [...this.snap.modals, id] });
  }

  closeModal(id: ModalId) {
    this.set({ modals: this.snap.modals.filter((m) => m !== id) });
  }

  /** Cascada de Escape: idéntica prioridad que el listener legacy. */
  handleEscape() {
    if (this.snap.modals.includes('matchConfig')) return this.closeModal('matchConfig');
    if (this.snap.menuVisible) return;
    if (this.snap.net.mapVote?.active) return;
    if (this.snap.modals.includes('gameMenu')) this.closeGameMenu();
    else this.openGameMenu();
  }

  /* ── Acciones de menú ───────────────────────────────────────────────── */

  playOffline() {
    if (!this.requireProfile()) return;
    if (this.game) this.game.networkSession = null;
    this.setOfflineHud();
    this.set({ menuVisible: false, notice: null, net: { ...OFFLINE_NET } });
  }

  openOnline() {
    if (!this.requireProfile()) return;
    if (!this.snap.onlineAvailable) {
      this.showNotice('Multiplayer está bloqueado hasta que el preflight conecte correctamente con el relay.', 'bad');
      void this.runPreflight();
      return;
    }
    this.set({ notice: null, screen: 'online' });
  }

  openCreate() {
    if (!this.requireProfile() || !this.snap.onlineAvailable) return this.openOnline();
    this.showScreen('create');
  }

  openBrowser() {
    if (!this.requireProfile() || !this.snap.onlineAvailable) return this.openOnline();
    this.showScreen('browser');
    // El contador arranca antes de medir pings: un host que no responde tarda
    // en agotar su probe y no debe retrasar la cuenta atrás visible.
    this.resetBrowserCountdown();
    void this.refreshServers();
  }

  async createMatch(settings: MatchSettings) {
    if (!this.requireProfile() || !this.snap.onlineAvailable) return this.openOnline();
    const session = this.prepareSession();
    this.set({
      screen: 'joining',
      joining: { title: 'Creando partida online…', value: 0.04, text: 'Inicializando host autoritativo…' },
    });
    try {
      await session.createMatch(settings, this.profile.getRelayUrl());
      this.updateReconnectOffer();
    } catch (error: any) {
      this.showNotice(error.message, 'bad');
      this.showScreen('create');
    }
  }

  /* ── Navegador de salas ─────────────────────────────────────────────── */

  private browserRefreshSeconds() {
    return Math.max(5, Number((NET_CONFIG as any).browserRefreshSeconds) || 12);
  }

  private resetBrowserCountdown() {
    this.set({ browser: { ...this.snap.browser, countdown: this.browserRefreshSeconds() } });
  }

  private stopBrowserCountdown() {
    if (this.snap.browser.countdown !== 0) this.set({ browser: { ...this.snap.browser, countdown: 0 } });
  }

  private browserCountdownTick() {
    // pollTick corre a 4 Hz; el contador baja 1 s cada 4 ticks.
    this.browserTick = (this.browserTick + 1) % 4;
    if (this.browserTick !== 0) return;
    const countdown = this.snap.browser.countdown - 1;
    if (countdown > 0) return this.set({ browser: { ...this.snap.browser, countdown } });
    this.resetBrowserCountdown();
    void this.refreshServers();
  }

  setBrowserFilter(patch: Partial<Pick<Snapshot['browser'], 'query' | 'modeFilter' | 'hideFull' | 'sort'>>) {
    this.set({ browser: { ...this.snap.browser, ...patch } });
  }

  async refreshServers() {
    if (!this.requireProfile() || !this.snap.onlineAvailable) return;
    // Medir el ping de cada sala puede tardar; evitamos solapar dos refrescos
    // (el manual y el automático) sobre la misma sesión de relay.
    if (this.snap.browser.refreshing) return;
    this.set({ browser: { ...this.snap.browser, refreshing: true, countdown: this.browserRefreshSeconds() } });
    const session = this.session && (this.session as any).role === 'offline' ? this.session : this.prepareSession();
    this.set({ browser: { ...this.snap.browser, servers: [], pings: {} } });
    try {
      await session.ensureRelay(this.profile.getRelayUrl());
      const result = await (session as any).relay.request('lobby:list', {});
      const servers: Lobby[] = (result.lobbies || []).map((lobby: Lobby) => ({ ...lobby, scope: 'public' }));
      this.preflightLobbyIds = new Set(servers.map((lobby) => String(lobby.id)));
      this.refreshReconnectAgainstKnownLobbies();
      this.set({ browser: { ...this.snap.browser, servers }, notice: null });
      await Promise.allSettled(servers.slice(0, 32).map(async (lobby) => {
        let ping = Infinity;
        try { ping = await (session as any).relay.measureLobbyPing(lobby.id); } catch (_) { /* sin respuesta */ }
        this.set({ browser: { ...this.snap.browser, pings: { ...this.snap.browser.pings, [String(lobby.id)]: ping } } });
      }));
    } catch (error: any) {
      this.set({ browser: { ...this.snap.browser, servers: [] } });
      this.showNotice(`Relay: ${error.message}`, 'bad');
    } finally {
      this.set({ browser: { ...this.snap.browser, refreshing: false } });
    }
  }

  chooseLobby(lobby: Lobby) {
    if (lobby.locked) {
      this.set({ passwordLobby: lobby });
      this.openModal('joinPassword');
    } else {
      void this.joinLobby(lobby, '');
    }
  }

  submitPassword(password: string) {
    const lobby = this.snap.passwordLobby;
    this.closeModal('joinPassword');
    this.set({ passwordLobby: null });
    if (lobby) void this.joinLobby(lobby, password);
  }

  cancelPassword() {
    this.closeModal('joinPassword');
    this.set({ passwordLobby: null });
  }

  private async joinLobby(lobby: Lobby, password: string) {
    if (!this.snap.onlineAvailable) return;
    const session = this.prepareSession();
    this.set({
      screen: 'joining',
      joining: { title: `Uniéndote a ${lobby.name}`, value: 0.1, text: 'Verificando sala en el relay…' },
    });
    try {
      await session.joinMatch(lobby, password, this.profile.getRelayUrl());
      this.updateReconnectOffer();
    } catch (error: any) {
      this.showNotice(error.message, 'bad');
      this.showScreen('browser');
    }
  }

  /* ── Reconexión a la última sesión ──────────────────────────────────── */

  private refreshReconnectAgainstKnownLobbies() {
    const last = this.profile?.getLastSession?.();
    if (last && this.snap.onlineAvailable && !this.preflightLobbyIds.has(String(last.lobbyId))) {
      this.profile.clearLastSession();
    }
    this.updateReconnectOffer();
  }

  private updateReconnectOffer() {
    const last = this.profile?.getLastSession?.();
    const known = !!(last && this.snap.onlineAvailable && this.preflightLobbyIds.has(String(last.lobbyId)));
    this.set({ reconnectOffer: known ? { lobbyName: last.lobbyName || 'Última partida' } : null });
  }

  async reconnectLast() {
    if (!this.requireProfile() || !this.snap.onlineAvailable) return this.openOnline();
    const last = this.profile.getLastSession();
    if (!last) { this.updateReconnectOffer(); return; }
    const session = this.prepareSession();
    this.set({
      screen: 'joining',
      joining: { title: `Reconectando a ${last.lobbyName || 'tu última partida'}`, value: 0.06, text: 'Confirmando que la partida todavía existe…' },
    });
    try {
      await session.ensureRelay(last.relayUrl || this.profile.getRelayUrl());
      const list = await (session as any).relay.request('lobby:list', {});
      const exists = (list.lobbies || []).some((lobby: Lobby) => String(lobby.id) === String(last.lobbyId));
      if (!exists) {
        this.profile.clearLastSession();
        this.preflightLobbyIds.delete(String(last.lobbyId));
        this.updateReconnectOffer();
        throw new Error('La última partida ya no existe en el relay.');
      }
      this.set({ joining: { ...this.snap.joining, value: 0.18, text: 'Reserva encontrada · recuperando identidad…' } });
      await session.resumeLast(last);
    } catch (error: any) {
      this.showNotice(error.message, 'bad');
      this.updateReconnectOffer();
      this.showScreen('main');
    }
  }

  reconnectNow() { this.session?.beginReconnect('manual'); }

  reconnectLeave() {
    this.session?.cancelReconnect();
    this.patchNet({ reconnect: null });
    void this.leaveOnline();
  }

  /* ── Salidas ────────────────────────────────────────────────────────── */

  async cancelJoin() {
    if (this.session) try { await this.session.leave({ keepLast: false }); } catch (_) { /* noop */ }
    this.game?.setNetworkSession(null);
    this.showScreen('main');
  }

  async leaveOnline() {
    if (this.session) try { await this.session.leave({ keepLast: false }); } catch (_) { /* noop */ }
    this.game?.setNetworkSession(null);
    this.game?.startNewCourse(this.game.makeSeed(), { quiet: true });
    this.setOfflineHud();
    this.set({
      menuVisible: true,
      screen: 'main',
      modals: [],
      net: { ...OFFLINE_NET },
    });
    this.updateReconnectOffer();
  }

  handlePageExit() {
    if (this.unloadHandled) return;
    this.unloadHandled = true;
    if (this.session?.getStatus?.().online) {
      // No se hace lobby:leave: la reserva cliente queda temporalmente en el relay.
      try { this.session.disconnectForUnload(); } catch (_) { /* noop */ }
    }
  }

  /* ── Menú de partida y votación ─────────────────────────────────────── */

  openGameMenu() {
    if (this.snap.menuVisible) return;
    this.openModal('gameMenu');
  }

  closeGameMenu() { this.closeModal('gameMenu'); }

  returnToShotOrigin() {
    if (this.game?.returnToShotOrigin()) this.closeGameMenu();
  }

  async returnHome() {
    this.closeGameMenu();
    if (this.session?.getStatus?.().online) return this.leaveOnline();
    this.set({ menuVisible: true, screen: 'main' });
  }

  requestMapVote() {
    const session = this.session;
    if (!session?.getStatus?.().online) return;
    const status = session.getMapVoteStatus();
    if (status.active) {
      this.closeGameMenu();
      this.patchNet({ mapVote: status });
      return;
    }
    if (status.cooldownRemainingMs > 0) {
      this.hud?.flashStatus(`Cambio de mapa disponible en ${formatRemaining(status.cooldownRemainingMs)}`, 'neutral', 1.2);
      return;
    }
    if (!session.requestMapVote()) {
      this.hud?.flashStatus('No se pudo enviar la votación · revisa la conexión', 'neutral', 1.1);
      return;
    }
    this.closeGameMenu();
  }

  castMapVote(choice: 'yes' | 'no') {
    const session = this.session;
    if (!session?.castLocalMapVote(choice)) return;
    this.patchNet({ mapVote: session.getStatus().online ? session.getMapVoteStatus() : null });
  }

  /* ── Getters para componentes ───────────────────────────────────────── */

  getSession() { return this.session; }
  getGame() { return this.game; }
  getGameMenuContext(): string {
    const session: any = this.session;
    const online = session?.getStatus?.().online;
    return online
      ? `${session.getStatus().settings?.mode === 'battle' ? 'Battle Royale' : 'Por turnos'} · ${session.role === 'host' ? 'Host' : 'Cliente'}`
      : 'Partida offline · recorrido procedural';
  }
}

export const sessionStore = new SessionStore();

export function useSession(): Snapshot {
  return useSyncExternalStore(sessionStore.subscribe, sessionStore.getSnapshot);
}
