import { sessionStore, useSession } from '../../bridge/sessionStore';

const VOTE_RING_CIRCUMFERENCE = 2 * Math.PI * 52;

export function MapVotePanel() {
  const snap = useSession();
  const status = snap.net.mapVote;
  const open = !!(snap.net.online && status?.active);
  const localKey = snap.net.localPlayerKey || '';
  const eligible = open && !!status && status.vote.electorate.includes(localKey);
  const voted = open && !!status && status.vote.yes.includes(localKey);
  const ratio = open && status && status.required > 0 ? Math.min(1, status.yes / status.required) : 0;

  return (
    <section id="mapVotePanel" className={`mini-modal${open ? '' : ' hidden'}`} aria-modal="true">
      <div className="mini-modal-card vote-card">
        <span className="kicker">VOTACIÓN UNÁNIME</span><h2>¿Cambiar de mapa?</h2>
        <p id="mapVoteText" className="modal-copy">
          {eligible
            ? (voted ? 'Tu voto ya es Sí. Esperando unanimidad del resto.' : 'Todos los jugadores conectados deben votar Sí. Un solo No cancela.')
            : 'Eres espectador: puedes ver la votación, pero no formas parte del electorado.'}
        </p>
        <div className="vote-ring">
          <svg viewBox="0 0 120 120" aria-hidden="true">
            <circle cx="60" cy="60" r="52" className="vote-ring-bg" />
            <circle
              id="mapVoteArc" cx="60" cy="60" r="52" className="vote-ring-arc"
              strokeDasharray="326.7"
              strokeDashoffset={VOTE_RING_CIRCUMFERENCE * (1 - ratio)}
            />
          </svg>
          <div className="vote-ring-read">
            <strong id="mapVoteYesCount">{status?.yes ?? 0}</strong>
            <span>de <b id="mapVoteNeedCount">{status?.required ?? 0}</b></span>
            <small>votos sí</small>
          </div>
        </div>
        <div className="modal-actions center">
          <button id="mapVoteNoBtn" className="secondary-button" type="button" disabled={!eligible || voted} onClick={() => sessionStore.castMapVote('no')}>NO</button>
          <button id="mapVoteYesBtn" className="submit-button" type="button" disabled={!eligible || voted} onClick={() => sessionStore.castMapVote('yes')}>SÍ · CAMBIAR</button>
        </div>
      </div>
    </section>
  );
}
