import { useEffect } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';

/**
 * Teclas globales: cascada de Escape (config → menú de juego) y focus-trap de
 * Tab dentro del panel de configuración. Puerto del listener legacy de menu.js.
 */
export function useGlobalKeys() {
  const { modals } = useSession();
  const matchConfigOpen = modals.includes('matchConfig');

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Tab' && matchConfigOpen) {
        const panel = document.getElementById('matchConfigPanel');
        if (!panel) return;
        const focusable = [...panel.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex]:not([tabindex="-1"])')]
          .filter((element) => !element.hidden && element.offsetParent !== null);
        if (focusable.length) {
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
          else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
        }
        return;
      }
      if (event.key !== 'Escape') return;
      sessionStore.handleEscape();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [matchConfigOpen]);
}
