import { memo, useRef } from 'react';

/**
 * El canvas del juego. Solo React lo crea; todo lo demás (bucle, física,
 * render) vive en el island imperativo que GameHost arranca desde App.
 * memo + sin props ⇒ React no vuelve a tocar este subárbol tras el montaje.
 */
export const GameCanvas = memo(function GameCanvas() {
  const ref = useRef<HTMLCanvasElement>(null);
  return <canvas id="game" ref={ref} aria-label="Juego de golf 2D procedural" />;
});
