import { useEffect, useRef, useState } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';

export function JoinPasswordPanel() {
  const snap = useSession();
  const open = snap.modals.includes('joinPassword');
  const [password, setPassword] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      setPassword('');
      const t = window.setTimeout(() => inputRef.current?.focus(), 30);
      return () => window.clearTimeout(t);
    }
  }, [open]);

  return (
    <section id="joinPasswordPanel" className={`mini-modal${open ? '' : ' hidden'}`} aria-modal="true">
      <form
        id="joinPasswordForm" className="mini-modal-card"
        onSubmit={(event) => { event.preventDefault(); sessionStore.submitPassword(password); }}
      >
        <span className="kicker">PARTIDA PRIVADA</span>
        <h2 id="joinPasswordTitle">{snap.passwordLobby?.name || 'Partida privada'}</h2>
        <label className="field">
          <span>Contraseña</span>
          <input
            id="joinPasswordInput" ref={inputRef} type="password" maxLength={72}
            autoComplete="current-password" value={password}
            onChange={(event) => setPassword(event.target.value)}
          />
        </label>
        <div className="modal-actions">
          <button id="cancelPasswordBtn" className="secondary-button" type="button" onClick={() => sessionStore.cancelPassword()}>Cancelar</button>
          <button className="submit-button" type="submit">UNIRME</button>
        </div>
      </form>
    </section>
  );
}
