// Estado y derivaciones puras del formulario "Crear partida".
// Sustituye al patrón legacy de leer los valores directamente del DOM.
import { NET_CONFIG } from '../game/net/netConfig';
import type { MatchSettings } from './types';

export const WORLD_IDS = Object.freeze(['meadow', 'sky-islands', 'cavern', 'aqua-cavern', 'hybrid', 'glacier'] as const);
export type WorldId = (typeof WORLD_IDS)[number];

export const WORLD_LABELS: Readonly<Record<string, string>> = Object.freeze({
  meadow: 'Pradera alta',
  'sky-islands': 'Islas flotantes',
  cavern: 'Cañón y túneles',
  'aqua-cavern': 'Cuevas submarinas',
  hybrid: 'Ruta híbrida',
  glacier: 'Glaciar cinético',
});

export interface CreateConfigState {
  name: string;
  password: string;
  mode: 'turn' | 'battle';
  maxPlayers: string;
  pointsEnabled: boolean;
  maxPoints: string;
  worldTimeEnabled: boolean;
  worldTimeSeconds: string;
  finishTimeEnabled: boolean;
  finishTimeSeconds: string;
  turnLimitEnabled: boolean;
  turnLimit: string;
  collisionsEnabled: boolean;
  allowedWorlds: WorldId[];
}

export const CREATE_DEFAULTS = Object.freeze({
  maxPlayers: 8,
  maxPoints: 5000,
  pointsEnabled: true,
  worldTimeSeconds: 180,
  worldTimeEnabled: false,
  finishTimeSeconds: 45,
  finishTimeEnabled: true,
  turnLimit: 12,
  turnLimitEnabled: false,
  collisionsEnabled: true,
});

export function initialCreateConfig(username: string): CreateConfigState {
  return {
    name: `${username || 'Jugador'} · Campo`,
    password: '',
    mode: 'turn',
    maxPlayers: String(CREATE_DEFAULTS.maxPlayers),
    pointsEnabled: CREATE_DEFAULTS.pointsEnabled,
    maxPoints: String(CREATE_DEFAULTS.maxPoints),
    worldTimeEnabled: CREATE_DEFAULTS.worldTimeEnabled,
    worldTimeSeconds: String(CREATE_DEFAULTS.worldTimeSeconds),
    finishTimeEnabled: CREATE_DEFAULTS.finishTimeEnabled,
    finishTimeSeconds: String(CREATE_DEFAULTS.finishTimeSeconds),
    turnLimitEnabled: CREATE_DEFAULTS.turnLimitEnabled,
    turnLimit: String(CREATE_DEFAULTS.turnLimit),
    collisionsEnabled: CREATE_DEFAULTS.collisionsEnabled,
    allowedWorlds: [...WORLD_IDS],
  };
}

export const boundedInt = (value: unknown, fallback: number, min: number, max: number): number => {
  const numeric = value === '' || value == null ? NaN : Number(value);
  return Math.max(min, Math.min(max, Math.round(Number.isFinite(numeric) ? numeric : fallback)));
};

export const durationText = (seconds: number): string => {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  if (total >= 60 && total % 60 === 0) return `${total / 60} min`;
  if (total >= 60) return `${Math.floor(total / 60)} min ${total % 60} s`;
  return `${total} s`;
};

export const formatInt = (value: unknown): string =>
  Math.max(0, Math.round(Number(value) || 0)).toLocaleString('es-ES');

/** Estado del formulario → settings normalizados (idéntico a readCreateSettings legacy). */
export function toMatchSettings(cfg: CreateConfigState, username: string): MatchSettings {
  return {
    name: cfg.name.trim() || `${username || 'Jugador'} · Campo`,
    password: cfg.password,
    mode: cfg.mode === 'battle' ? 'battle' : 'turn',
    maxPlayers: boundedInt(cfg.maxPlayers, CREATE_DEFAULTS.maxPlayers, 2, (NET_CONFIG as any).maxPlayers),
    maxPoints: cfg.pointsEnabled ? boundedInt(cfg.maxPoints, CREATE_DEFAULTS.maxPoints, 500, 1000000) : null,
    infinitePoints: !cfg.pointsEnabled,
    worldTimeSeconds: cfg.worldTimeEnabled ? boundedInt(cfg.worldTimeSeconds, CREATE_DEFAULTS.worldTimeSeconds, 30, 1800) : null,
    finishCountdownSeconds: cfg.finishTimeEnabled ? boundedInt(cfg.finishTimeSeconds, CREATE_DEFAULTS.finishTimeSeconds, 10, 300) : null,
    maxTurnsPerWorld: cfg.turnLimitEnabled ? boundedInt(cfg.turnLimit, CREATE_DEFAULTS.turnLimit, 1, 100) : null,
    allowedWorlds: cfg.allowedWorlds.length ? [...cfg.allowedWorlds] : [...WORLD_IDS],
    collisionsEnabled: cfg.mode === 'battle' && cfg.collisionsEnabled,
  };
}

/** Textos del resumen (antes updateCreateSummary escribía el DOM a mano). */
export function summaryTexts(cfg: CreateConfigState, username: string) {
  const s = toMatchSettings(cfg, username);
  const locked = s.password.length > 0;
  return {
    name: s.name,
    mode: s.mode === 'battle' ? 'Battle Royale' : 'Por turnos',
    players: `${s.maxPlayers} máx.`,
    points: s.maxPoints == null ? 'Sin límite' : `${formatInt(s.maxPoints)} pts`,
    timing: s.finishCountdownSeconds != null
      ? `${durationText(s.finishCountdownSeconds)} al llegar`
      : s.worldTimeSeconds != null ? durationText(s.worldTimeSeconds) : 'Sin reloj',
    worlds: `${s.allowedWorlds.length} activo${s.allowedWorlds.length === 1 ? '' : 's'}`,
    access: locked ? 'Privada' : 'Pública',
    trigger: `${s.maxPlayers} jugadores · ${s.maxPoints == null ? '∞ puntos' : `${formatInt(s.maxPoints)} puntos`} · ${s.allowedWorlds.length} ambiente${s.allowedWorlds.length === 1 ? '' : 's'}`,
    hint: s.mode === 'battle'
      ? `Todos lanzan a la vez${s.collisionsEnabled ? ' y las bolas colisionan' : ''}; llegar antes suma bonus de posición.`
      : 'Un jugador lanza cada vez. La cámara sigue al turno activo y el orden avanza al detenerse la bola.',
  };
}

export const formatRemaining = (ms: number): string => {
  const total = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return m ? `${m}:${String(s).padStart(2, '0')}` : `${s}s`;
};

export const hashName = (text: string): number => {
  let h = 2166136261;
  for (const ch of String(text || '')) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
};

export const colorFor = (name: string): string => {
  const colors = (NET_CONFIG as any).colors as string[];
  return colors[hashName(name) % colors.length];
};

// Sugerencias de nombre generadas en local: ninguna llamada externa.
const NAME_PREFIX = ['Águila', 'Birdie', 'Bunker', 'Caddie', 'Driver', 'Eagle', 'Hierro', 'Putt', 'Sand', 'Wedge', 'Green', 'Fairway'];
const NAME_SUFFIX = ['Veloz', 'Táctico', 'Cósmico', 'Sur', 'Norte', 'Nitro', 'Prisma', 'Turbo', 'Zen', 'Volcán', 'Ártico', 'Neón'];

export function suggestName(): string {
  const pick = (list: string[]) => list[Math.floor(Math.random() * list.length)];
  return `${pick(NAME_PREFIX)}${pick(NAME_SUFFIX)}`.slice(0, (NET_CONFIG as any).maxNameLength);
}
