import { sessionStore, useSession } from '../../bridge/sessionStore';
import { formatRemaining } from '../../bridge/createConfig';

export function GameMenuPanel() {
  const snap = useSession();
  const open = snap.modals.includes('gameMenu');
  const online = snap.net.online;
  const mapVote = snap.net.mapVote;
  const game = sessionStore.getGame();

  const voteRemain = mapVote?.cooldownRemainingMs ?? 0;
  const voteLabel = mapVote?.active
    ? 'VOTACIÓN EN CURSO'
    : voteRemain > 0
      ? `ENFRIAMIENTO · ${formatRemaining(voteRemain)}`
      : 'VOTAR CAMBIO DE MAPA';

  return (
    <section id="gameMenuPanel" className={`mini-modal${open ? '' : ' hidden'}`} aria-modal="true">
      <div className="mini-modal-card game-menu-card">
        <span className="kicker">PARTIDA</span><h2>Menú de juego</h2>
        <p id="gameMenuContext" className="modal-copy">{sessionStore.getGameMenuContext()}</p>
        <div className="game-menu-actions">
          <button id="resumeGameBtn" className="submit-button" type="button" onClick={() => sessionStore.closeGameMenu()}>
            <svg className="ico" aria-hidden="true"><use href="#i-play" /></svg>CONTINUAR
          </button>
          <button
            id="resetShotBtn" className="secondary-button" type="button"
            title="Devuelve la bola al punto donde comenzó el tiro actual y suma un golpe"
            disabled={open ? !game?.canReturnToShotOrigin() : true}
            onClick={() => sessionStore.returnToShotOrigin()}
          >
            <svg className="ico" aria-hidden="true"><use href="#i-refresh" /></svg><span>VOLVER AL PUNTO DEL TIRO · +1</span>
          </button>
          <button
            id="requestMapVoteBtn"
            className={`secondary-button${online ? '' : ' hidden'}`}
            type="button"
            disabled={!online || voteRemain > 0 || !!mapVote?.active}
            title={voteRemain > 0 ? `Disponible en ${formatRemaining(voteRemain)}` : ''}
            onClick={() => sessionStore.requestMapVote()}
          >
            <svg className="ico" aria-hidden="true"><use href="#i-map" /></svg><span id="requestMapVoteLabel">{voteLabel}</span>
          </button>
          <button id="returnHomeBtn" className="secondary-button danger-outline" type="button" onClick={() => void sessionStore.returnHome()}>
            <svg className="ico" aria-hidden="true"><use href="#i-exit" /></svg>
            <span>{online ? 'DESCONECTAR Y VOLVER AL INICIO' : 'VOLVER AL INICIO'}</span>
          </button>
        </div>
      </div>
    </section>
  );
}
