/* ── MatchBar (≤4 Hz desde el store) ───────────────────────────────────── */

function MatchBar() {
  const { net } = useSession();
  const view = useMemo(() => {
    if (!net.online || !net.status) {
      return {
        mode: 'offline', state: 'idle', badge: 'OFFLINE', icon: '#i-flag',
        title: 'Partida libre', hint: 'Sin red · recorrido procedural de 3 hoyos', timer: null as string | null,
      };
    }
    const h = deriveNetHeader(net.status, net.standings);
    return {
      mode: h.mode,
      state: h.bar.tone === 'mine' ? 'your-turn' : h.bar.tone === 'over' ? 'over' : h.bar.tone === 'spectator' ? 'spectator' : 'waiting',
      badge: h.mode === 'battle' ? 'BATTLE' : 'TURNOS',
      icon: h.mode === 'battle' ? '#i-swords' : '#i-turns',
      title: h.bar.title,
      hint: h.bar.hint,
      timer: timeText(h.clockSeconds),
    };
  }, [net.online, net.status, net.standings]);

  return (
    <section id="matchBar" className="dock dock-tc match-bar" data-mode={view.mode} data-state={view.state} aria-live="polite">
      <span id="matchModeBadge" className="mode-badge" data-mode={view.mode}>
        <svg className="ico" aria-hidden="true"><use href={view.icon} /></svg><b>{view.badge}</b>
      </span>
      <div className="match-state">
        <strong id="matchStateLabel">{view.title}</strong>
        <small id="matchStateHint">{view.hint}</small>
      </div>
      <span id="matchTimer" className="match-timer" hidden={view.timer == null}>{view.timer ?? '00:00'}</span>
      <i id="matchTurnPulse" className="turn-pulse" aria-hidden="true" />
    </section>
  );
}

/* ── Dock superior derecho: viento (estático) + NetChip + botones ──────── */

function TopRightDock() {
  const { net } = useSession();
  const chip = useMemo(() => {
    if (!net.online || !net.status) return { ping: '—', bars: 0, role: 'OFFLINE', quality: 'offline' };
    const h = deriveNetHeader(net.status, net.standings);
    return {
      ping: h.q.key === 'none' ? '—' : `${Math.round(h.rtt)}`,
      bars: h.q.bars,
      role: h.roleText,
      quality: h.q.key === 'none' ? 'offline' : h.q.key,
    };
  }, [net.online, net.status, net.standings]);

  return (
    <section className="dock dock-tr" aria-label="Condiciones y controles">
      <div className="wind-gauge" title="Viento del hoyo">
        <div className="wind-dial">
          <svg viewBox="0 0 44 44" className="wind-ring" aria-hidden="true">
            <circle cx="22" cy="22" r="19" className="wind-ring-bg" />
            <circle id="windRingArc" cx="22" cy="22" r="19" className="wind-ring-arc" strokeDasharray="119.4" strokeDashoffset="119.4" />
          </svg>
          <i id="windArrow" className="wind-needle" aria-hidden="true" />
        </div>
        <div className="wind-read">
          <span id="windTitleLabel" className="stat-label">VIENTO</span>
          <strong id="windLabel">0.0 m/s</strong>
        </div>
      </div>

      <button id="netChip" className="net-chip" type="button" data-quality={chip.quality} title="Métricas de red (F3)" onClick={() => sessionStore.toggleMetrics()}>
        <i id="netChipBars" className="signal-bars" data-bars={String(chip.bars)}><b /><b /><b /><b /></i>
        <span className="net-chip-read"><strong id="netChipPing">{chip.ping}</strong><small id="netChipRole">{chip.role}</small></span>
      </button>

      <div className="hud-buttons">
        <button
          id="newCourseBtn" className={`hud-btn${net.online ? ' hidden' : ''}`} type="button"
          title="Generar un campo nuevo con otra seed"
          onClick={() => gameHost.game?.requestNewCourse()}
        >
          <svg className="ico" aria-hidden="true"><use href="#i-dice" /></svg><span>Nuevo campo</span>
        </button>
        <button
          id="gameMenuBtn" className="hud-btn icon-only" type="button"
          title="Menú de partida (Esc)" aria-label="Menú de partida"
          onClick={() => sessionStore.openGameMenu()}
        >
          <svg className="ico" aria-hidden="true"><use href="#i-menu" /></svg>
        </button>
      </div>
    </section>
  );
}

/* ── Marcador online (aside derecho) ───────────────────────────────────── */

function ScoreRow({ row, mode, metricMode }: { row: StandingRow & Record<string, any>; mode: string; metricMode: 'strokes' | 'ping' }) {
  const q = quality(row.ping);
  const classes = ['score-row'];
  if (row.local) classes.push('is-local');
  if (row.turn) classes.push('is-turn');
  if (!row.connected) classes.push('is-offline');
  if (row.finished) classes.push('is-finished');
  if (row.rank <= 3) classes.push(`is-podium-${row.rank}`);

  const tag = row.role === 'spectator' ? 'ESP' : row.local ? 'TÚ' : '';
  let metric: string;
  if (metricMode === 'ping') {
    metric = Number.isFinite(row.ping as number) && (row.ping as number) > 0 ? `${Math.round(row.ping as number)}ms` : '—';
  } else if (!row.finished) metric = `${row.strokes}g`;
  else if (row.finishReason === 'holed') metric = `✓ ${row.strokes}`;
  else if (row.finishReason === 'turn-limit') metric = `LÍM. ${row.strokes}`;
  else if (row.timedOut) metric = 'TIEMPO';
  else metric = '—';

  // El avance hacia el hoyo solo aporta información en Battle Royale.
  const showProgress = mode === 'battle' && row.role === 'player' && Number.isFinite(row.progress);

  return (
    <div className={classes.join(' ')}>
      <span className="row-rank">{row.rank}</span>
      <div className="row-id">
        <i className="player-color" style={{ background: row.color, color: row.color }} />
        <span className="player-name">{row.username}</span>
        <b className="row-tag" hidden={!tag} data-tag={tag.toLowerCase() || undefined}>{tag}</b>
        <i
          className="ping-dot" data-q={row.connected ? q.key : 'none'}
          title={Number.isFinite(row.ping as number) && (row.ping as number) > 0 ? `${Math.round(row.ping as number)} ms · ${q.label}` : 'Ping sin medir'}
        />
      </div>
      <span className="row-metric">{metric}</span>
      <strong className="row-points">{formatInt(row.points)}</strong>
      <div className="row-progress" hidden={!showProgress} style={showProgress ? { color: row.color } : undefined}>
        <i style={showProgress ? { width: `${Math.round(Math.max(0, Math.min(1, row.progress)) * 100)}%` } : undefined} />
      </div>
    </div>
  );
}

function NetworkHudAside() {
  const { net } = useSession();
  const [collapsed, setCollapsed] = useState(false);
  const [metricMode, setMetricMode] = useState<'strokes' | 'ping'>('strokes');

  // Al entrar a una partida nueva el marcador vuelve a desplegarse.
  useEffect(() => { if (net.online) setCollapsed(false); }, [net.online]);

  const h = useMemo(
    () => (net.online && net.status ? deriveNetHeader(net.status, net.standings) : null),
    [net.online, net.status, net.standings],
  );

  if (!h) {
    return <aside id="networkHud" className="dock dock-r network-hud hidden" aria-label="Estado multijugador" />;
  }

  const maxPoints = h.settings.maxPoints;
  const leader = net.standings.reduce((best, p) => Math.max(best, p.points || 0), 0);
  const goalRatio = maxPoints == null ? 0 : Math.max(0, Math.min(1, leader / Math.max(1, maxPoints)));

  return (
    <aside id="networkHud" className={`dock dock-r network-hud${collapsed ? ' collapsed' : ''}`} aria-label="Estado multijugador">
      <header className="net-head">
        <div className="net-head-main">
          <span id="netModeLabel" className="mode-badge sm" data-mode={h.mode}>
            <svg className="ico" aria-hidden="true"><use href={h.mode === 'battle' ? '#i-swords' : '#i-turns'} /></svg>
            <b>{h.mode === 'battle' ? 'BATTLE ROYALE' : 'POR TURNOS'}</b>
          </span>
          <strong id="netLobbyLabel">{h.lobbyName}</strong>
        </div>
        <div className="net-head-actions">
          <button id="scoreboardToggle" className="icon-button ghost" type="button" title="Plegar marcador" aria-label="Plegar marcador" onClick={() => setCollapsed((c) => !c)}>
            <svg className="ico" aria-hidden="true"><use href="#i-chart" /></svg>
          </button>
          <button id="leaveOnlineBtn" className="icon-button danger" type="button" title="Salir de la partida" aria-label="Salir de la partida" onClick={() => void sessionStore.leaveOnline()}>
            <svg className="ico" aria-hidden="true"><use href="#i-exit" /></svg>
          </button>
        </div>
      </header>

      <div className="net-meta">
        <span id="netRoleLabel" className="net-role" data-role={h.spectator ? 'spectator' : net.status.role}>{h.roleText}</span>
        <span className="net-meta-sep" />
        <span className="net-meta-item"><svg className="ico" aria-hidden="true"><use href="#i-users" /></svg><b id="netPlayerCount">{h.connected}/{h.settings.maxPlayers || net.standings.length || 0}</b></span>
        <span className="net-meta-item">
          <svg className="ico" aria-hidden="true"><use href="#i-turns" /></svg>
          <b
            id="netTimerLabel" data-phase={net.status.timerPhase || 'elapsed'}
            title={net.status.timerPhase === 'finish' ? 'Tiempo restante para terminar el mundo' : (net.status.timerPhase === 'world' ? 'Tiempo restante del mundo' : 'Tiempo total de partida')}
          >
            {timeText(h.clockSeconds)}
          </b>
        </span>
        <span className="signal-wrap">
          <i id="netSignalBars" className="signal-bars" data-bars={String(h.q.bars)} aria-label={`${h.q.bars} de 4 barras de señal`}><b /><b /><b /><b /></i>
          <span id="netSignalLabel">{h.q.key === 'none' ? 'midiendo…' : `${Math.round(h.rtt)} ms · ${h.q.label}`}</span>
        </span>
      </div>

      <div id="turnIndicator" className="turn-indicator" data-state={h.bar.tone}>{h.bar.scoreboardText}</div>

      <div id="netGoalBar" className="goal-bar" hidden={maxPoints == null}>
        <div className="goal-track"><i id="netGoalFill" style={{ width: `${(goalRatio * 100).toFixed(1)}%` }} /></div>
        <div className="goal-read"><span>OBJETIVO</span><strong id="netGoalLabel">{`${formatInt(leader)} / ${formatInt(maxPoints ?? 0)} pts`}</strong></div>
      </div>

      <div className="scoreboard">
        <div className="scoreboard-head">
          <span>#</span><span>JUGADOR</span>
          <span
            id="scoreboardMetric" style={{ cursor: 'pointer' }} title="Alternar entre golpes y ping"
            onClick={() => setMetricMode((m) => (m === 'strokes' ? 'ping' : 'strokes'))}
          >
            {metricMode === 'ping' ? 'PING' : 'GOLPES'}
          </span>
          <span>PTS</span>
        </div>
        <div id="scoreboardRows" className="scoreboard-rows">
          {net.standings.map((row) => (
            <ScoreRow key={row.playerKey} row={row} mode={h.mode} metricMode={metricMode} />
          ))}
        </div>
      </div>

      <footer className="net-foot">
        <span id="netFootHint">
          {net.status.role === 'host'
            ? 'Eres la autoridad de física de esta sala'
            : 'El host es la autoridad de física · tu vista está interpolada'}
        </span>
      </footer>
    </aside>
  );
}

/* ── Panel de métricas (F3) ────────────────────────────────────────────── */

const HISTORY = 60;

function drawPingGraph(canvas: HTMLCanvasElement, history: number[]) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);

  ctx.strokeStyle = 'rgba(255,255,255,.07)';
  ctx.lineWidth = 1;
  for (let i = 1; i < 3; i += 1) {
    const y = Math.round((h / 3) * i) + 0.5;
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
  }
  if (history.length < 2) return;

  const max = Math.max(60, ...history) * 1.15;
  const step = w / (HISTORY - 1);
  const pointY = (value: number) => h - (Math.min(value, max) / max) * (h - 4) - 2;

  ctx.beginPath();
  history.forEach((value, index) => {
    const x = index * step;
    const y = pointY(value);
    if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  });
  const last = history[history.length - 1];
  ctx.strokeStyle = last <= 70 ? '#5ff3d2' : last <= 150 ? '#ffd479' : '#ff7f70';
  ctx.lineWidth = 1.6;
  ctx.stroke();

  ctx.lineTo((history.length - 1) * step, h);
  ctx.lineTo(0, h);
  ctx.closePath();
  ctx.fillStyle = last <= 70 ? 'rgba(95,243,210,.13)' : last <= 150 ? 'rgba(255,212,121,.13)' : 'rgba(255,127,112,.13)';
  ctx.fill();
}

function metricTone(value: number | null | undefined, good: number, fair: number): string {
  if (!Number.isFinite(value as number)) return '';
  const v = value as number;
  if (v <= good) return 'good';
  if (v <= fair) return 'fair';
  return 'bad';
}

function Metric({ label, value, tone, id }: { label: string; value: string; tone?: string; id: string }) {
  return <div className="metric"><span>{label}</span><strong id={id} data-tone={tone || ''}>{value}</strong></div>;
}

function MetricsPanel() {
  const snap = useSession();
  const open = snap.metricsOpen;
  const stats = snap.net.online ? snap.net.netStats : null;
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (open && canvasRef.current) drawPingGraph(canvasRef.current, snap.net.pingHistory);
  }, [open, snap.net.pingHistory]);

  // FPS/partículas se leen del island en el momento del render; el panel se
  // re-renderiza a 4 Hz por los cambios del snapshot mientras está online, y
  // por el propio toggle cuando no.
  const hud = gameHost.hud;
  const fps = hud?.fps || 0;
  const frameMs = hud?.frameMs || 0;
  const particles = gameHost.game?.particles?.items?.length || 0;
  const fmt = (v: unknown, suffix: string, digits = 0) =>
    Number.isFinite(v as number) ? `${digits ? (v as number).toFixed(digits) : Math.round(v as number)}${suffix}` : '—';

  return (
    <section id="metricsPanel" className={`metrics-panel${open ? '' : ' hidden'}`} aria-label="Métricas técnicas">
      <header>
        <svg className="ico" aria-hidden="true"><use href="#i-chart" /></svg><strong>MÉTRICAS</strong>
        <button id="metricsClose" className="icon-button ghost" type="button" aria-label="Cerrar métricas" onClick={() => sessionStore.closeMetrics()}>
          <svg className="ico" aria-hidden="true"><use href="#i-close" /></svg>
        </button>
      </header>
      <div className="metrics-grid">
        <Metric id="mFps" label="FPS" value={fps ? String(fps) : '—'} tone={fps >= 55 ? 'good' : fps >= 35 ? 'fair' : 'bad'} />
        <Metric id="mFrame" label="FRAME" value={frameMs ? `${frameMs.toFixed(1)} ms` : '—'} />
        <Metric id="mPing" label="PING" value={fmt(stats?.ping, ' ms')} tone={metricTone(stats?.ping, 70, 150)} />
        <Metric id="mJitter" label="JITTER" value={fmt(stats?.jitter, ' ms')} tone={metricTone(stats?.jitter, 12, 35)} />
        <Metric id="mSnap" label="SNAPSHOTS" value={Number.isFinite(stats?.snapshotHz) ? `${stats.snapshotHz.toFixed(1)} Hz` : '—'} />
        <Metric id="mLoss" label="PÉRDIDA" value={Number.isFinite(stats?.lossPercent) ? `${stats.lossPercent.toFixed(1)} %` : '—'} tone={metricTone(stats?.lossPercent, 1, 5)} />
        <Metric id="mRelay" label="RELAY" value={fmt(stats?.relayRtt, ' ms')} tone={metricTone(stats?.relayRtt, 90, 200)} />
        <Metric id="mRole" label="ROL" value={String(stats?.role || 'OFFLINE').toUpperCase()} />
        <Metric id="mPeers" label="PEERS" value={String(stats?.peers ?? 0)} />
        <Metric id="mParticles" label="PARTÍCULAS" value={String(particles)} />
        {/* Capa de suavizado: pasos de simulación, buffer de interpolación,
             desfase de reloj y corrección visual pendiente. */}
        <Metric id="mSim" label="SIM" value={stats?.simulationHz ? `${stats.simulationHz} Hz · ${stats.stepsLastFrame ?? 0}×` : '—'} />
        <Metric id="mInterp" label="INTERP" value={fmt(stats?.interpolationMs, ' ms')} tone={metricTone(stats?.interpolationMs, 90, 160)} />
        <Metric id="mClock" label="RELOJ" value={fmt(stats?.clockDriftMs, ' ms')} tone={metricTone(Math.abs(stats?.clockDriftMs ?? NaN), 12, 45)} />
        <Metric id="mCorrection" label="CORRECCIÓN" value={Number.isFinite(stats?.correctionDistance) ? `${stats.correctionDistance.toFixed(1)} px` : '—'} tone={metricTone(stats?.correctionDistance, 8, 40)} />
      </div>
      <div className="metrics-graph"><canvas id="metricsGraph" ref={canvasRef} width={252} height={46} /><small>Ping · últimos 60 s</small></div>
    </section>
  );
}

/* ── Capa completa ─────────────────────────────────────────────────────── */

export function HudLayer() {
  return (
    <div className="hud-layer" aria-label="Interfaz de partida">
      <TopLeftDock />
      <MatchBar />
      <TopRightDock />
      <WorldInfoDock />
      <ShotDock />
      <NetworkHudAside />
      <MetricsPanel />
      <div id="statusToast" className="status-toast" data-tone="neutral" aria-live="polite">Listo</div>
    </div>
  );
}
