import { useMemo } from 'react';
import { sessionStore, useSession } from '../../bridge/sessionStore';
import { durationText, formatInt, WORLD_IDS, WORLD_LABELS } from '../../bridge/createConfig';
import { quality } from '../../game/net/netQuality';
import type { Lobby } from '../../bridge/types';

function ServerTooltip({ lobby }: { lobby: Lobby }) {
  const id = `server-details-${String(lobby.id || 'room').replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const world = lobby.worldLabel || WORLD_LABELS[lobby.worldArchetype || ''] || 'Aún por generar';
  const difficulty = lobby.difficultyLabel || 'Por definir';
  const allowed = Array.isArray(lobby.allowedWorlds) && lobby.allowedWorlds.length ? lobby.allowedWorlds : [...WORLD_IDS];
  const allowedText = allowed.length === WORLD_IDS.length
    ? 'Todos los ambientes'
    : allowed.map((id2) => WORLD_LABELS[id2] || id2).join(' · ');

  const rules: Array<[string, string] | [string, string, true]> = [
    ['Jugadores', `${lobby.currentPlayers || 0} / ${lobby.maxPlayers || 0}`],
    ['Objetivo', lobby.maxPoints == null ? 'Sin límite' : `${formatInt(lobby.maxPoints)} pts`],
    ['Tiempo del mundo', lobby.worldTimeSeconds == null ? 'Sin límite' : durationText(lobby.worldTimeSeconds)],
    ['Cuando alguien emboca', lobby.finishCountdownSeconds == null ? 'Desactivado' : durationText(lobby.finishCountdownSeconds)],
    ['Lanzamientos', lobby.maxTurnsPerWorld == null ? 'Sin límite' : `${lobby.maxTurnsPerWorld} por mundo`],
    ['Colisiones', lobby.mode === 'battle' ? (lobby.collisionsEnabled !== false ? 'Activadas' : 'Desactivadas') : 'No aplica'],
    ['Cambio de mapa', 'Votación unánime · cada 1 min'],
    ['Mundos permitidos', allowedText, true],
  ];

  return (
    <div className="server-tooltip" id={id} role="tooltip">
      <div className="server-tooltip-current">
        <span>{lobby.started ? `MUNDO ${(lobby.holeIndex || 0) + 1} EN CURSO` : 'PRÓXIMO MUNDO'}</span>
        <strong>{world}</strong>
        <small>{difficulty}{lobby.mapSize ? ` · ${lobby.mapSize}` : ''}</small>
      </div>
      <div className="server-tooltip-rules">
        {rules.map(([label, value, wide]) => (
          <span key={label} className={`server-tooltip-rule${wide ? ' wide' : ''}`}>
            <small>{label}</small><b>{value}</b>
          </span>
        ))}
      </div>
    </div>
  );
}

function ServerRow({ lobby, ping }: { lobby: Lobby; ping: number | undefined }) {
  const battle = lobby.mode === 'battle';
  const started = !!lobby.started;
  const current = lobby.currentPlayers || 0;
  const max = lobby.maxPlayers || 0;
  const full = max > 0 && current >= max;
  const q = quality(Number.isFinite(ping as number) ? (ping as number) : null);
  const detailsId = `server-details-${String(lobby.id || 'room').replace(/[^a-zA-Z0-9_-]/g, '')}`;

  return (
    <div className="server-row" data-started={String(started)} tabIndex={0} aria-describedby={detailsId}>
      <div className="server-name-cell">
        <div className="server-name-line">
          <svg className={lobby.locked ? 'ico locked' : 'ico'} aria-hidden="true"><use href={lobby.locked ? '#i-lock' : '#i-unlock'} /></svg>
          <strong>{lobby.name || 'Partida'}</strong>
        </div>
        <div className="server-sub">
          <i className="status-dot" data-status={started ? 'started' : 'waiting'} />
          <small>
            {started
              ? `En curso · mundo ${(lobby.holeIndex || 0) + 1} · ${lobby.worldLabel || WORLD_LABELS[lobby.worldArchetype || ''] || 'generado'} · ${lobby.difficultyLabel || 'dificultad por definir'}`
              : 'Esperando jugadores · el primer tiro inicia'}
          </small>
        </div>
      </div>

      <div className="server-mode">
        <span className="mode-badge sm" data-mode={battle ? 'battle' : 'turn'}>
          <svg className="ico" aria-hidden="true"><use href={battle ? '#i-swords' : '#i-turns'} /></svg>
          <b>{battle ? 'BATTLE' : 'TURNOS'}</b>
        </span>
        <small>{lobby.maxPoints == null ? '∞ puntos' : `${formatInt(lobby.maxPoints)} pts`}</small>
      </div>

      <div className="server-players">
        <strong>{current}<span> / {max}</span></strong>
        <div className="player-meter" data-full={String(full)}>
          <i style={{ width: `${max > 0 ? Math.round((current / max) * 100) : 0}%` }} />
        </div>
      </div>

      <div className="server-signal">
        <i className="signal-bars" data-bars={String(q.bars)}><b /><b /><b /><b /></i>
        <strong>{Number.isFinite(ping as number) ? `${ping} ms` : '…'}</strong>
        <small>{q.label}</small>
      </div>

      <button
        className="join-server-button" type="button" disabled={full}
        data-kind={started ? 'spectate' : 'join'}
        onClick={() => sessionStore.chooseLobby(lobby)}
      >
        {full ? 'LLENA' : (started ? 'ESPECTAR' : 'UNIRME')}
      </button>

      <ServerTooltip lobby={lobby} />
    </div>
  );
}

export function BrowserScreen() {
  const snap = useSession();
  const active = snap.screen === 'browser';
  const { servers, pings, refreshing, countdown, query, modeFilter, hideFull, sort } = snap.browser;

  const filtered = useMemo(() => {
    const q = query.trim().toLocaleLowerCase('es');
    const list = servers.filter((lobby) => {
      if (q && !String(lobby.name || '').toLocaleLowerCase('es').includes(q)) return false;
      if (modeFilter !== 'all') {
        const mode = lobby.mode === 'battle' ? 'battle' : 'turn';
        if (mode !== modeFilter) return false;
      }
      if (hideFull && (lobby.currentPlayers || 0) >= (lobby.maxPlayers || 0)) return false;
      return true;
    });
    const ping = (lobby: Lobby) => pings[String(lobby.id)] ?? 999999;
    return [...list].sort((a, b) => {
      if (sort === 'players') return (b.currentPlayers || 0) - (a.currentPlayers || 0) || String(a.name).localeCompare(String(b.name));
      if (sort === 'name') return String(a.name).localeCompare(String(b.name));
      if (sort === 'status') return Number(!!a.started) - Number(!!b.started) || String(a.name).localeCompare(String(b.name));
      return ping(a) - ping(b);
    });
  }, [servers, pings, query, modeFilter, hideFull, sort]);

  const countText = servers.length
    ? `${filtered.length} de ${servers.length} partida${servers.length === 1 ? '' : 's'} visibles`
    : refreshing ? 'Consultando…' : 'Sin partidas publicadas';

  return (
    <section id="screenBrowser" className={`menu-screen browser-screen${active ? ' active' : ''}`}>
      <div className="screen-toolbar">
        <button className="back-button" type="button" aria-label="Volver" onClick={() => sessionStore.showScreen('online')}>
          <svg className="ico" aria-hidden="true"><use href="#i-back" /></svg>
        </button>
        <div><span className="kicker">SERVER BROWSER</span><h2>Buscar partidas</h2></div>
        <button id="refreshServersBtn" className="refresh-button" type="button" onClick={() => void sessionStore.refreshServers()}>
          <svg className="ico" aria-hidden="true"><use href="#i-refresh" /></svg><span>Actualizar</span>
        </button>
      </div>

      <div className="browser-controls">
        <label className="search-box">
          <svg className="ico" aria-hidden="true"><use href="#i-search" /></svg>
          <input
            id="serverSearchInput" type="search" placeholder="Buscar por nombre…"
            value={query} onChange={(e) => sessionStore.setBrowserFilter({ query: e.target.value })}
          />
        </label>
        <div className="filter-tabs" id="modeFilter" role="group" aria-label="Filtrar por modo">
          {(['all', 'turn', 'battle'] as const).map((mode) => (
            <button
              key={mode} type="button" data-filter={mode}
              className={modeFilter === mode ? 'active' : ''}
              onClick={() => sessionStore.setBrowserFilter({ modeFilter: mode })}
            >
              {mode === 'all' ? 'Todos' : mode === 'turn' ? 'Turnos' : 'Battle'}
            </button>
          ))}
        </div>
        <label className="toggle-field inline">
          <input id="hideFullToggle" type="checkbox" checked={hideFull} onChange={(e) => sessionStore.setBrowserFilter({ hideFull: e.target.checked })} />
          <i /><span>Ocultar llenas</span>
        </label>
        <label className="sort-field">
          <span>Ordenar</span>
          <select id="serverSort" value={sort} onChange={(e) => sessionStore.setBrowserFilter({ sort: e.target.value as any })}>
            <option value="ping">Ping</option>
            <option value="players">Jugadores</option>
            <option value="name">Nombre</option>
            <option value="status">Estado</option>
          </select>
        </label>
      </div>

      <div className="browser-summary">
        <span id="serverCount">{countText}</span>
        <span id="autoRefreshLabel" className="auto-refresh">{active && countdown > 0 ? `Auto ${countdown}s` : ''}</span>
      </div>

      <div className="server-list-head"><span>PARTIDA</span><span>MODO</span><span>JUGADORES</span><span>SEÑAL</span><span></span></div>
      <div id="serverList" className="server-list">
        {refreshing && !servers.length ? (
          <div className="empty-state"><span className="spinner-small" /> Consultando el relay público…</div>
        ) : !filtered.length ? (
          <div className="empty-state">
            {servers.length ? 'Ninguna partida coincide con los filtros activos.' : 'No hay partidas públicas visibles ahora mismo.'}
            <small>{servers.length ? 'Prueba a limpiar la búsqueda o el filtro de modo.' : 'Puedes crear la tuya desde “Crear partida”.'}</small>
          </div>
        ) : (
          filtered.map((lobby) => <ServerRow key={String(lobby.id)} lobby={lobby} ping={pings[String(lobby.id)]} />)
        )}
      </div>
      <div className="browser-legend">
        <span><svg className="ico" aria-hidden="true"><use href="#i-shield" /></svg>Todos los hosts visibles se publicaron mediante el relay configurado.</span>
        <span><svg className="ico" aria-hidden="true"><use href="#i-users" /></svg>Las partidas en curso te dejan entrar como espectador hasta el próximo hoyo.</span>
      </div>
    </section>
  );
}
