import { memo } from 'react';
import { gameHost } from '../../bridge/GameHost';

/**
 * Resultado de hoyo. React monta el esqueleto UNA vez; hud.showResult() y
 * hideResult() escriben los textos y el atributo hidden desde el bucle de
 * juego (evento de 60 Hz: pasar por el store añadiría latencia sin ganancia).
 */
export const MessagePanel = memo(function MessagePanel() {
  return (
    <section id="messagePanel" className="overlay-panel hidden" aria-live="polite">
      <div className="result-card">
        <span id="messageEyebrow" className="kicker">HOYO COMPLETADO</span>
        <h1 id="messageTitle">Birdie</h1>
        <p id="messageBody">Buen tiro.</p>
        <div id="messageStats" className="result-stats" />
        <button id="continueBtn" className="submit-button" type="button" onClick={() => gameHost.game?.continueAfterResult()}>
          CONTINUAR
        </button>
      </div>
    </section>
  );
});
